(412319, 36364, 9504, '<td valign="top">This is the black and yellow garden spider.  They are harmless to humans.  Aren''t they gorgeous?  Nice shot.</td>', 'This is the black and yellow garden spider.  They are harmless to humans.  Aren''t they gorgeous?  Nice shot.', '2003-09-08 11:22:16.000000', NULL, 1),
(412320, 36169, 9504, '<td valign="top">Exceptional colors!  I wish I could have seen more of the flower though...  Consider cropping out the top more.  There is a lot of excess space above...</td>', 'Exceptional colors!  I wish I could have seen more of the flower though...  Consider cropping out the top more.  There is a lot of excess space above...', '2003-09-08 11:23:19.000000', NULL, 1),
