(412572, 36880, 327, '<td valign="top">Wonderful shot......wonderful composition and colors.</td>', 'Wonderful shot......wonderful composition and colors.', '2003-09-08 14:05:05.000000', NULL, 1),
(412573, 36557, 327, '<td valign="top">Nice one.....really good color, focus. Nice nice.</td>', 'Nice one.....really good color, focus. Nice nice.', '2003-09-08 14:05:31.000000', NULL, 1),
(412577, 36778, 327, '<td valign="top">Very cool. Looks like one of the hummingbird moths. Nice capture, good job.</td>', 'Very cool. Looks like one of the hummingbird moths. Nice capture, good job.', '2003-09-08 14:10:25.000000', NULL, 1),
(412591, 36446, 472, '<td valign="top">i expected to see this concept repeated but it wasnt ! good one! :)</td>', 'i expected to see this concept repeated but it wasnt ! good one! :)', '2003-09-08 14:31:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(412592, 36292, 327, '<td valign="top">Fantastic humor. Love the creativity....Congrats really well done.</td>', 'Fantastic humor. Love the creativity....Congrats really well done.', '2003-09-08 14:31:16.000000', NULL, 1),
(412594, 36470, 327, '<td valign="top">Very well done...love the colors.</td>', 'Very well done...love the colors.', '2003-09-08 14:32:11.000000', NULL, 1),
(412596, 36578, 327, '<td valign="top">Old mother Hubbard? ......fantastic find.</td>', 'Old mother Hubbard? ......fantastic find.', '2003-09-08 14:32:36.000000', NULL, 1),
(412615, 36652, 9452, '<td valign="top">Too small...</td>', 'Too small...', '2003-09-08 15:03:54.000000', NULL, 1),
(412617, 36879, 1041, '<td valign="top">You sure did get close up and personal ... maybe a bit too much.  While the composition is nice, the technical execution lets you down ... something needs to be in focus, and with living creatures, it''s usually the eyes.  A little contrast enhancement could also improve the shot IMO.</td>', 'You sure did get close up and personal ... maybe a bit too much.  While the composition is nice, the technical execution lets you down ... something needs to be in focus, and with living creatures, it''s usually the eyes.  A little contrast enhancement could also improve the shot IMO.', '2003-09-08 15:16:55.000000', NULL, 1),
(412618, 36856, 8522, '<td valign="top">One of my favourites, great combination of colours and composition. The dragonfly is a little small for the frame, but the result is still pleasing. Nice dof. 9</td>', 'One of my favourites, great combination of colours and composition. The dragonfly is a little small for the frame, but the result is still pleasing. Nice dof. 9', '2003-09-08 15:17:02.000000', NULL, 1),
(412619, 36292, 8522, '<td valign="top">Nicely setup, effective background and lighting. Not sure about the weighting of negative space in your crop. You ''posed'' the beetle nicely. Good dof. 9</td>', 'Nicely setup, effective background and lighting. Not sure about the weighting of negative space in your crop. You ''posed'' the beetle nicely. Good dof. 9', '2003-09-08 15:18:08.000000', NULL, 1),
(412622, 36784, 8522, '<td valign="top">Fantastic, I''m a sucker for drinking butterfly shots. This would be perfect without the extra stem of purple flowers in the top left. The butterfly is nicely lit. 9</td>', 'Fantastic, I''m a sucker for drinking butterfly shots. This would be perfect without the extra stem of purple flowers in the top left. The butterfly is nicely lit. 9', '2003-09-08 15:19:23.000000', NULL, 1),
(412633, 36756, 3569, '<td valign="top">Nice close-up.</td>', 'Nice close-up.', '2003-09-08 15:29:48.000000', NULL, 1),
(412634, 36824, 3569, '<td valign="top">great shot, especially like the angle.</td>', 'great shot, especially like the angle.', '2003-09-08 15:30:30.000000', NULL, 1),
(412637, 36760, 3569, '<td valign="top">nice action shot.</td>', 'nice action shot.', '2003-09-08 15:32:22.000000', NULL, 1),
(412639, 36725, 3569, '<td valign="top">Appears overexposed. I think I see an insect, but...</td>', 'Appears overexposed. I think I see an insect, but...', '2003-09-08 15:35:17.000000', NULL, 1),
(412641, 36435, 3569, '<td valign="top">Movement or focus making the shot look kind of blury.</td>', 'Movement or focus making the shot look kind of blury.', '2003-09-08 15:35:53.000000', NULL, 1),
(412642, 36449, 3569, '<td valign="top">on gay feathers (the flower).. Nice colors andcontrasts.</td>', 'on gay feathers (the flower).. Nice colors andcontrasts.', '2003-09-08 15:36:44.000000', NULL, 1),
(412645, 36292, 3569, '<td valign="top">Great idea and weevil shot.</td>', 'Great idea and weevil shot.', '2003-09-08 15:40:57.000000', NULL, 1),
(412647, 36247, 8522, '<td valign="top">Nicely backlit moth. Superb background. Only thing I don''t like is the composition... I don''t think centred butterflies/ moths work well in photos, especially as the eye is drawn primarily to the eyes first. With a different crop, I would have given this a 10. Instead: 9</td>', 'Nicely backlit moth. Superb background. Only thing I don''t like is the composition... I don''t think centred butterflies/ moths work well in photos, especially as the eye is drawn primarily to the eyes first. With a different crop, I would have given this a 10. Instead: 9', '2003-09-08 15:44:51.000000', NULL, 1),
(412648, 36477, 3569, '<td valign="top">A tea party?  Nice shot..</td>', 'A tea party?  Nice shot..', '2003-09-08 15:45:58.000000', NULL, 1),
(412649, 36841, 8522, '<td valign="top">Fabulous, I must remember this technique in my photos to allow the viewer to use their own imagination by hinting at the subject. Dof is great here. Very humourous. 8</td>', 'Fabulous, I must remember this technique in my photos to allow the viewer to use their own imagination by hinting at the subject. Dof is great here. Very humourous. 8', '2003-09-08 15:46:16.000000', NULL, 1),
(412650, 36693, 3569, '<td valign="top">I really like this shot, but a bit more contrast would have brought out more colors of the greens and yellow/orange butterfly.</td>', 'I really like this shot, but a bit more contrast would have brought out more colors of the greens and yellow/orange butterfly.', '2003-09-08 15:47:03.000000', NULL, 1),
(412651, 36832, 8522, '<td valign="top">Superb title, I like this very much. Shame his legs are blurred and burnt out. Everything else is excellent. 7</td>', 'Superb title, I like this very much. Shame his legs are blurred and burnt out. Everything else is excellent. 7', '2003-09-08 15:47:20.000000', NULL, 1),
(412653, 36726, 3569, '<td valign="top">great idea, but the wasp looks quite dead, not scary at all.</td>', 'great idea, but the wasp looks quite dead, not scary at all.', '2003-09-08 15:48:33.000000', NULL, 1),
(412654, 36572, 3569, '<td valign="top">It couldn''t be any better.  Simply beautiful....  Best of insect show...</td>', 'It couldn''t be any better.  Simply beautiful....  Best of insect show...', '2003-09-08 15:49:53.000000', NULL, 1),
(412660, 36448, 6576, '<td valign="top">WOW</td>', 'WOW', '2003-09-08 16:00:27.000000', NULL, 1),
(412701, 36796, 3554, '<td valign="top">One of my favorites...I hate bees. I love how the legs are all standing straight up.</td>', 'One of my favorites...I hate bees. I love how the legs are all standing straight up.', '2003-09-08 16:55:03.000000', NULL, 1),
(412703, 36823, 3554, '<td valign="top">Good use of black and white.</td>', 'Good use of black and white.', '2003-09-08 16:55:26.000000', NULL, 1),
(412704, 36754, 11034, '<td valign="top">I like this one. One of my fav this week.</td>', 'I like this one. One of my fav this week.', '2003-09-08 16:56:11.000000', NULL, 1),
(412705, 36760, 3554, '<td valign="top">I love how you caught this in midair. I tried to get a few mid air shots and coultn''t pull it off. <br/> <br/>I wish the lighting weren''t so dark, but that''s really my only "complaint."</td>', 'I love how you caught this in midair. I tried to get a few mid air shots and coultn''t pull it off.  I wish the lighting weren''t so dark, but that''s really my only "complaint."', '2003-09-08 16:56:32.000000', NULL, 1),
(412708, 36020, 3554, '<td valign="top">Interesting shot, good color. I think I''ld like to see more of the bug in focus. DOF might be to shallow in this case.</td>', 'Interesting shot, good color. I think I''ld like to see more of the bug in focus. DOF might be to shallow in this case.', '2003-09-08 16:57:55.000000', NULL, 1),
(412710, 36678, 3554, '<td valign="top">I love the concept but wish more of it were in focus, or that the bug was in focus.</td>', 'I love the concept but wish more of it were in focus, or that the bug was in focus.', '2003-09-08 16:58:27.000000', NULL, 1),
(412712, 36832, 3554, '<td valign="top">Interesting DOF and position of the mantis.  Colors/lighting a bit dull for my tastes but it''s hard to get it all to come together when you have to hunt your subject.</td>', 'Interesting DOF and position of the mantis.  Colors/lighting a bit dull for my tastes but it''s hard to get it all to come together when you have to hunt your subject.', '2003-09-08 16:59:58.000000', NULL, 1),
(412713, 36690, 3554, '<td valign="top">Interesting lighting, but feels over sharpened.</td>', 'Interesting lighting, but feels over sharpened.', '2003-09-08 17:00:32.000000', NULL, 1),
(412717, 36292, 3554, '<td valign="top">Great DOF, it really sets the bug off. I like the box and capturing him escaping...it adds story what could have been just another picture of an insect.</td>', 'Great DOF, it really sets the bug off. I like the box and capturing him escaping...it adds story what could have been just another picture of an insect.', '2003-09-08 17:03:58.000000', NULL, 1),
(412721, 36629, 4210, '<td valign="top">Interesting, but I don''t like what you did with the DOF. Love the colour and composition though.</td>', 'Interesting, but I don''t like what you did with the DOF. Love the colour and composition though.', '2003-09-08 17:10:55.000000', NULL, 1),
(412722, 36852, 4210, '<td valign="top">Interesting composition. Not very high definition though...</td>', 'Interesting composition. Not very high definition though...', '2003-09-08 17:11:49.000000', NULL, 1),
(412723, 36539, 4210, '<td valign="top">Very nifty. I like the negative space etc.</td>', 'Very nifty. I like the negative space etc.', '2003-09-08 17:13:07.000000', NULL, 1),
(412724, 36527, 4210, '<td valign="top">Nice colour, although I would have cropped out the body of the bug and just had the wings. It would have been more abstract, but still.</td>', 'Nice colour, although I would have cropped out the body of the bug and just had the wings. It would have been more abstract, but still.', '2003-09-08 17:13:54.000000', NULL, 1),
(412729, 36884, 4210, '<td valign="top">Noisy, but interesting.</td>', 'Noisy, but interesting.', '2003-09-08 17:15:47.000000', NULL, 1),
(412734, 36742, 10643, '<td valign="top">Nice, but I wish it was closer, and the bug''s position in the frame is weird. The negative space doesn''t add much.<br/>[ps. Is this really a fly? I''m terrified of all yellow-and-black-striped insects (serious bee sting allergy) so I would run in fear from this. How comforting to know it isn''t a bee. Wonder if they bite.]</td>', 'Nice, but I wish it was closer, and the bug''s position in the frame is weird. The negative space doesn''t add much.[ps. Is this really a fly? I''m terrified of all yellow-and-black-striped insects (serious bee sting allergy) so I would run in fear from this. How comforting to know it isn''t a bee. Wonder if they bite.]', '2003-09-08 17:18:03.000000', NULL, 1),
(412737, 36873, 10643, '<td valign="top">wonderful composition! so refreshing to see bright summer colors after all this camouflage! my favorite so far :)</td>', 'wonderful composition! so refreshing to see bright summer colors after all this camouflage! my favorite so far :)', '2003-09-08 17:19:49.000000', NULL, 1),
(412739, 36652, 7703, '<td valign="top">To small</td>', 'To small', '2003-09-08 17:22:55.000000', NULL, 1),
(412742, 36535, 10768, '<td valign="top">I like the purplish hues in the background which match the coloring of the spider.  Nice composition.  I like this photo because there''s more to view in this photo than just one bug.</td>', 'I like the purplish hues in the background which match the coloring of the spider.  Nice composition.  I like this photo because there''s more to view in this photo than just one bug.', '2003-09-08 17:28:01.000000', NULL, 1),
(412743, 36203, 10768, '<td valign="top">I like the point of view on this shot.  Looks like the spider is coming right towards the viewer.  Nice work.</td>', 'I like the point of view on this shot.  Looks like the spider is coming right towards the viewer.  Nice work.', '2003-09-08 17:29:49.000000', NULL, 1),
(412750, 36672, 3290, '<td valign="top">Nicely exposed, but the bee is a little too small in the shot and not quite in focus.</td>', 'Nicely exposed, but the bee is a little too small in the shot and not quite in focus.', '2003-09-08 17:49:08.000000', NULL, 1),
(412751, 36697, 3290, '<td valign="top">Nice catch (for you and the spider :-) Not a lot to criticise here - focus and exposure is good. Compostion isn''t exciting but it does the job. Good one.</td>', 'Nice catch (for you and the spider :-) Not a lot to criticise here - focus and exposure is good. Compostion isn''t exciting but it does the job. Good one.', '2003-09-08 17:50:13.000000', NULL, 1),
(412752, 36815, 3290, '<td valign="top">What is it? We don''t get things like that round here (at least, I don''t think we do). Would have been better to see its head - ideally on a contrasting background, but you have to take what you can get. Focus is on its rump, rather than its head. Cool beast!</td>', 'What is it? We don''t get things like that round here (at least, I don''t think we do). Would have been better to see its head - ideally on a contrasting background, but you have to take what you can get. Focus is on its rump, rather than its head. Cool beast!', '2003-09-08 17:51:49.000000', NULL, 1),
(412754, 36547, 3290, '<td valign="top">Nice pose and composition, but a bit overexposed. I find these critters'' heads look out of focus even when they are in focus - I think its the eyes and hairs. Nice catch.</td>', 'Nice pose and composition, but a bit overexposed. I find these critters'' heads look out of focus even when they are in focus - I think its the eyes and hairs. Nice catch.', '2003-09-08 17:53:16.000000', NULL, 1),
(412757, 36824, 3290, '<td valign="top">Hmm. Could be the winner. Interesting subject, nice composition, good exposure and focus and lovely colours too. It even (with the title) tells a story. Very nice job - well done. <br/> <br/>PS Lovely noise-free image  - 10D?</td>', 'Hmm. Could be the winner. Interesting subject, nice composition, good exposure and focus and lovely colours too. It even (with the title) tells a story. Very nice job - well done.  PS Lovely noise-free image  - 10D?', '2003-09-08 17:55:40.000000', NULL, 1),
(412760, 36317, 3290, '<td valign="top">Interesting viewpoint and they''re great subjects, but I don''t think the bright background''s done you any favours - i overpowers the subject. Still a nice shot, though.</td>', 'Interesting viewpoint and they''re great subjects, but I don''t think the bright background''s done you any favours - i overpowers the subject. Still a nice shot, though.', '2003-09-08 17:57:49.000000', NULL, 1),
(412761, 36086, 3290, '<td valign="top">Nice bee shot, but composition feels unbalanced. Good exposure and sharpness though.</td>', 'Nice bee shot, but composition feels unbalanced. Good exposure and sharpness though.', '2003-09-08 17:58:45.000000', NULL, 1),
(412764, 36020, 3290, '<td valign="top">Nice close-up - great detail in the eyes. What''s it sitting on? Whatever it is, it''s effective. Nice shot which I think will do well.</td>', 'Nice close-up - great detail in the eyes. What''s it sitting on? Whatever it is, it''s effective. Nice shot which I think will do well.', '2003-09-08 17:59:38.000000', NULL, 1),
(412765, 36292, 3290, '<td valign="top">:-) Simple and effective. Good shot.</td>', ':-) Simple and effective. Good shot.', '2003-09-08 18:00:00.000000', NULL, 1),
(412767, 36037, 8130, '<td valign="top">This is so sick and twisted!  I love it.  8-)</td>', 'This is so sick and twisted!  I love it.  8-)', '2003-09-08 18:01:43.000000', NULL, 1),
(412768, 36020, 5792, '<td valign="top">Incredible macro. Great color and clarity. Perfect focus for the such a shallow DOF. Cropped beatifully. One of the best images in one of the most competitive challenges in recent times.</td>', 'Incredible macro. Great color and clarity. Perfect focus for the such a shallow DOF. Cropped beatifully. One of the best images in one of the most competitive challenges in recent times.', '2003-09-08 18:02:33.000000', NULL, 1),
(412769, 36054, 11570, '<td valign="top">Fantastic colours</td>', 'Fantastic colours', '2003-09-08 18:02:44.000000', NULL, 1),
(412770, 36429, 3290, '<td valign="top">Very nice backlit spider - got the exposure just right on it. Well done.</td>', 'Very nice backlit spider - got the exposure just right on it. Well done.', '2003-09-08 18:02:55.000000', NULL, 1),
(412771, 36841, 11570, '<td valign="top">A sense of menace, just what is about to appear.</td>', 'A sense of menace, just what is about to appear.', '2003-09-08 18:03:27.000000', NULL, 1),
(412773, 36364, 3290, '<td valign="top">Creepy. A tad bright on the back there, from the flash.Interesting subject</td>', 'Creepy. A tad bright on the back there, from the flash.Interesting subject', '2003-09-08 18:03:36.000000', NULL, 1),
(412774, 36203, 5792, '<td valign="top">Excellant, excellant image. Superb clarity.</td>', 'Excellant, excellant image. Superb clarity.', '2003-09-08 18:03:54.000000', NULL, 1),
(412775, 36578, 11570, '<td valign="top">What is the surface?  Is this a captive spider? Certainly amazing</td>', 'What is the surface?  Is this a captive spider? Certainly amazing', '2003-09-08 18:04:21.000000', NULL, 1),
(412776, 36459, 5792, '<td valign="top">Exceptional clarity and perfect background. The flower highlighs the insect nicely.</td>', 'Exceptional clarity and perfect background. The flower highlighs the insect nicely.', '2003-09-08 18:05:02.000000', NULL, 1),
(412778, 36296, 5792, '<td valign="top">Superb!</td>', 'Superb!', '2003-09-08 18:05:33.000000', NULL, 1),
(412780, 36874, 10643, '<td valign="top">Excellent, but would like to see more context, a blurred background or colored lighting behind, or something</td>', 'Excellent, but would like to see more context, a blurred background or colored lighting behind, or something', '2003-09-08 18:06:08.000000', NULL, 1),
(412781, 36247, 11570, '<td valign="top">I never see them stay still long enough to take the picture.  Well done</td>', 'I never see them stay still long enough to take the picture.  Well done', '2003-09-08 18:06:12.000000', NULL, 1),
(412782, 36802, 5792, '<td valign="top">Exceptional technical high quality in this image. Great color.</td>', 'Exceptional technical high quality in this image. Great color.', '2003-09-08 18:06:18.000000', NULL, 1),
(412783, 36471, 10643, '<td valign="top">Are these those massive things in New Zealand? I''m terrified! Outstanding color and focus, wish I knew what kind of leaf that was so as to get more of a sense of scale, especially since wetas are so big.</td>', 'Are these those massive things in New Zealand? I''m terrified! Outstanding color and focus, wish I knew what kind of leaf that was so as to get more of a sense of scale, especially since wetas are so big.', '2003-09-08 18:07:21.000000', NULL, 1),
(412784, 36796, 10643, '<td valign="top">Dead bees are one of my favorite things in the world. 6</td>', 'Dead bees are one of my favorite things in the world. 6', '2003-09-08 18:07:36.000000', NULL, 1),
(412786, 36874, 5792, '<td valign="top">Excellant image. Nicely framed and the white background is perfect. Slightly more contrast on the bug itself would make this beautiful image even better.</td>', 'Excellant image. Nicely framed and the white background is perfect. Slightly more contrast on the bug itself would make this beautiful image even better.', '2003-09-08 18:08:15.000000', NULL, 1),
(412788, 36760, 11570, '<td valign="top">Just needs the wings beating like a hummingbird to make it just bit greater a capture.  Amazing none the less.</td>', 'Just needs the wings beating like a hummingbird to make it just bit greater a capture.  Amazing none the less.', '2003-09-08 18:08:45.000000', NULL, 1),
(412789, 36086, 11333, '<td valign="top">Great shot!</td>', 'Great shot!', '2003-09-08 18:09:08.000000', NULL, 1),
(412790, 36806, 5792, '<td valign="top">Nice angle on the butterfly. Good clarity.</td>', 'Nice angle on the butterfly. Good clarity.', '2003-09-08 18:09:18.000000', NULL, 1),
(412791, 36824, 10643, '<td valign="top">Love the colors in this one</td>', 'Love the colors in this one', '2003-09-08 18:10:22.000000', NULL, 1),
(412792, 36776, 5792, '<td valign="top">One of the most creative insect image in the challenge. Nice way to show the Mantis from two different angles</td>', 'One of the most creative insect image in the challenge. Nice way to show the Mantis from two different angles', '2003-09-08 18:10:59.000000', NULL, 1),
(412793, 36020, 10643, '<td valign="top">WOW, you got soooo close! What an amazing shot.</td>', 'WOW, you got soooo close! What an amazing shot.', '2003-09-08 18:11:14.000000', NULL, 1),
(412794, 36242, 3290, '<td valign="top">It''s interesting, but a bit hard to tell what''s going on. Good composition and nice contrast between the trunk and the background.</td>', 'It''s interesting, but a bit hard to tell what''s going on. Good composition and nice contrast between the trunk and the background.', '2003-09-08 18:11:38.000000', NULL, 1),
(412795, 36470, 5792, '<td valign="top">Classic Dragonfly shot. I like the way you have enough DOF to almost get the whole bug in focus. You need a lot for that angle.</td>', 'Classic Dragonfly shot. I like the way you have enough DOF to almost get the whole bug in focus. You need a lot for that angle.', '2003-09-08 18:12:38.000000', NULL, 1),
(412796, 36771, 3290, '<td valign="top">Pretty subject and setting. A tad soft, but I don''t think that hurts much in this case. Very nice.</td>', 'Pretty subject and setting. A tad soft, but I don''t think that hurts much in this case. Very nice.', '2003-09-08 18:12:59.000000', NULL, 1),
(412797, 36572, 5792, '<td valign="top">Beautidul capture. The green leaf and dark background serves as a perfect backdrop to highlight the subject. Perfect focus. Excellant color. Just the right amount of contrast. Brilliant.</td>', 'Beautidul capture. The green leaf and dark background serves as a perfect backdrop to highlight the subject. Perfect focus. Excellant color. Just the right amount of contrast. Brilliant.', '2003-09-08 18:14:33.000000', NULL, 1),
(412799, 36340, 5792, '<td valign="top">Overall excellant image. Soft green in background is very nice.</td>', 'Overall excellant image. Soft green in background is very nice.', '2003-09-08 18:15:32.000000', NULL, 1),
(412802, 36780, 5792, '<td valign="top">Nice capture. Green against the lavender flower petals is very nice.</td>', 'Nice capture. Green against the lavender flower petals is very nice.', '2003-09-08 18:16:50.000000', NULL, 1),
(412804, 36477, 5792, '<td valign="top">Very nice macro. Well framed. Good clarity.</td>', 'Very nice macro. Well framed. Good clarity.', '2003-09-08 18:18:27.000000', NULL, 1),
(412805, 36818, 5792, '<td valign="top">Nicely done spider image.</td>', 'Nicely done spider image.', '2003-09-08 18:19:06.000000', NULL, 1),
(412809, 36756, 5792, '<td valign="top">Excellant strait on view. Great background color to highlight your subject. Nice framing of the bug''s right antenna.</td>', 'Excellant strait on view. Great background color to highlight your subject. Nice framing of the bug''s right antenna.', '2003-09-08 18:21:10.000000', NULL, 1),
(412810, 36866, 5792, '<td valign="top">Use of B&amp;W in this images highights its excellant clarity.</td>', 'Use of B&W in this images highights its excellant clarity.', '2003-09-08 18:22:21.000000', NULL, 1),
(412812, 36867, 5792, '<td valign="top">Nice worker bee profile. Excellant colors and background. Beautiful all the way around.</td>', 'Nice worker bee profile. Excellant colors and background. Beautiful all the way around.', '2003-09-08 18:23:17.000000', NULL, 1),
(412814, 36829, 5792, '<td valign="top">Super smooth soft background. No pixelation here.</td>', 'Super smooth soft background. No pixelation here.', '2003-09-08 18:24:31.000000', NULL, 1),
(412816, 36749, 5792, '<td valign="top">Great angle. An all around tremendous image. Would like to see just a tad more contrast.</td>', 'Great angle. An all around tremendous image. Would like to see just a tad more contrast.', '2003-09-08 18:25:55.000000', NULL, 1),
(412817, 36557, 5792, '<td valign="top">One outstanding shot! Wonderful subject clarity in this close-up</td>', 'One outstanding shot! Wonderful subject clarity in this close-up', '2003-09-08 18:27:02.000000', NULL, 1),
(412819, 36693, 5792, '<td valign="top">One of the best of the Monarchs. Good capture.</td>', 'One of the best of the Monarchs. Good capture.', '2003-09-08 18:27:54.000000', NULL, 1),
