(412981, 36856, 2716, '<td valign="top">Wow!  what a wonderful combination of colors.  Totally gorgeous.  Though the colors seem to be the main appeal of the photo, the dragon fly really adds a nice touch.  Good luck.  Jacko.  9</td>', 'Wow!  what a wonderful combination of colors.  Totally gorgeous.  Though the colors seem to be the main appeal of the photo, the dragon fly really adds a nice touch.  Good luck.  Jacko.  9', '2003-09-08 21:15:08.000000', NULL, 1),
(412982, 36672, 2883, '<td valign="top">Catchy title, but it implies that the focus should be more on the bee and zoomed in a bit more. The overall color could be enhanced a bit.</td>', 'Catchy title, but it implies that the focus should be more on the bee and zoomed in a bit more. The overall color could be enhanced a bit.', '2003-09-08 21:15:30.000000', NULL, 1),
