(413402, 36884, 6624, '<td valign="top">monochromatic approach leaves me feeling a bit dull</td>', 'monochromatic approach leaves me feeling a bit dull', '2003-09-09 11:31:19.000000', NULL, 1),
(413403, 36020, 6624, '<td valign="top">those eyes are great, but so it the big grin</td>', 'those eyes are great, but so it the big grin', '2003-09-09 11:31:40.000000', NULL, 1),
