(413407, 36775, 6624, '<td valign="top">nice light</td>', 'nice light', '2003-09-09 11:33:24.000000', NULL, 1),
(413410, 36778, 11893, '<td valign="top">Striking color contrasts and combos..only nature could pull it off and you\''ve captured it beautifully</td>', 'Striking color contrasts and combos..only nature could pull it off and you\''ve captured it beautifully', '2003-09-09 11:39:13.000000', NULL, 1),
