(413419, 36799, 6624, '<td valign="top">the legs all loaded up with pollen are nice - it falls into something that appears muddy and too soft a focus for me</td>', 'the legs all loaded up with pollen are nice - it falls into something that appears muddy and too soft a focus for me', '2003-09-09 12:08:22.000000', NULL, 1),
(413423, 36448, 6624, '<td valign="top">I love this idea -- I wish it had been possible to achieve more clarity<br/>I also love the way the fly seems to be swimming/flying through the viscous amber</td>', 'I love this idea -- I wish it had been possible to achieve more clarityI also love the way the fly seems to be swimming/flying through the viscous amber', '2003-09-09 12:12:22.000000', NULL, 1),
(413424, 36843, 2350, '<td valign="top">Another 10 from me in this challenge.  <br/>What an interesting photo you captured.  It''s another 10 for me.  You deserve a winner.<br/><br/><i>Message edited by magnetic9999 - remove extra lines.</i></td>', 'Another 10 from me in this challenge.  What an interesting photo you captured.  It''s another 10 for me.  You deserve a winner.Message edited by magnetic9999 - remove extra lines.', '2003-09-09 12:14:07.000000', NULL, 1),
(413426, 36796, 8296, '<td valign="top">Cute idea!</td>', 'Cute idea!', '2003-09-09 12:16:06.000000', NULL, 1),
(413427, 36785, 8296, '<td valign="top">Beautiful composition.  Good sharpness and depth of field.  Nice shot!</td>', 'Beautiful composition.  Good sharpness and depth of field.  Nice shot!', '2003-09-09 12:17:07.000000', NULL, 1),
(413428, 36313, 2350, '<td valign="top">Great shot as there were a couple 10''s from me in this challenge.  Good luck</td>', 'Great shot as there were a couple 10''s from me in this challenge.  Good luck', '2003-09-09 12:19:28.000000', NULL, 1),
(413431, 36873, 7969, '<td valign="top">I like your idea, it is a creative take on the challenge. Good title too, I like the way the light hits the water and the delicate way the petals of the flower ''break thru the water''.</td>', 'I like your idea, it is a creative take on the challenge. Good title too, I like the way the light hits the water and the delicate way the petals of the flower ''break thru the water''.', '2003-09-09 12:30:27.000000', NULL, 1),
(413432, 36292, 10643, '<td valign="top">excellent!</td>', 'excellent!', '2003-09-09 12:31:24.000000', NULL, 1),
(413434, 36292, 7969, '<td valign="top">Great use of depth of field, way to capture the critter ''escaping'', good title too. Nice job.</td>', 'Great use of depth of field, way to capture the critter ''escaping'', good title too. Nice job.', '2003-09-09 12:31:37.000000', NULL, 1),
(413436, 36802, 7969, '<td valign="top">I would be curious how shot would look if it were rotated, not really a critque just curious.   nice job.</td>', 'I would be curious how shot would look if it were rotated, not really a critque just curious.   nice job.', '2003-09-09 12:33:15.000000', NULL, 1),
(413437, 36545, 7969, '<td valign="top">Well done.</td>', 'Well done.', '2003-09-09 12:33:39.000000', NULL, 1),
(413438, 36768, 7969, '<td valign="top">He really is furry,  eeeekkk  :  )!! nice shot, good use of DOF</td>', 'He really is furry,  eeeekkk  :  )!! nice shot, good use of DOF', '2003-09-09 12:34:33.000000', NULL, 1),
(413439, 36471, 7969, '<td valign="top">Sharp, clear image, good depth of field.</td>', 'Sharp, clear image, good depth of field.', '2003-09-09 12:35:09.000000', NULL, 1),
(413440, 36726, 7969, '<td valign="top">Ok I want to know how you got the bee (and model!!) to pose for this shot!!??  Grat job, good creative approach.</td>', 'Ok I want to know how you got the bee (and model!!) to pose for this shot!!??  Grat job, good creative approach.', '2003-09-09 12:36:15.000000', NULL, 1),
(413441, 36086, 7969, '<td valign="top">Clear sharp shot, good macro and composition.</td>', 'Clear sharp shot, good macro and composition.', '2003-09-09 12:36:57.000000', NULL, 1),
(413445, 36875, 7969, '<td valign="top">It is actually the flower in your shot that I really like, it almost looks fake, nice combination, good job.</td>', 'It is actually the flower in your shot that I really like, it almost looks fake, nice combination, good job.', '2003-09-09 12:38:33.000000', NULL, 1),
(413447, 36871, 7969, '<td valign="top">Excellent choice of subjects, interesting, clear sharp focus.  Background is slightly overexposed but blurred effect takes away from it as does the subject.</td>', 'Excellent choice of subjects, interesting, clear sharp focus.  Background is slightly overexposed but blurred effect takes away from it as does the subject.', '2003-09-09 12:39:51.000000', NULL, 1),
(413455, 36557, 7969, '<td valign="top">Good shot,wishing the antanae had we more room on top.  Very well done tho.</td>', 'Good shot,wishing the antanae had we more room on top.  Very well done tho.', '2003-09-09 12:43:27.000000', NULL, 1),
(413457, 36169, 7969, '<td valign="top">2 bugs for the price of one,  nice capture.  What I find most impressive about your shot is that you were able to get several ''depths'' focused and still blurred the very background one.</td>', '2 bugs for the price of one,  nice capture.  What I find most impressive about your shot is that you were able to get several ''depths'' focused and still blurred the very background one.', '2003-09-09 12:48:46.000000', NULL, 1),
(413459, 36882, 7969, '<td valign="top">Great texture and color in his wings.</td>', 'Great texture and color in his wings.', '2003-09-09 12:49:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(413460, 36851, 7969, '<td valign="top">LOL good title, great job, it is cropped a little tight on the left, but a great image.</td>', 'LOL good title, great job, it is cropped a little tight on the left, but a great image.', '2003-09-09 12:50:47.000000', NULL, 1),
(413464, 36780, 7969, '<td valign="top">hmm, so is this a bee?  I have never see a green bee.</td>', 'hmm, so is this a bee?  I have never see a green bee.', '2003-09-09 12:54:32.000000', NULL, 1),
(413465, 36796, 7969, '<td valign="top">LOL, did you kill this bug for the purpose of this shot?  Poor thing :  ).   Very clear and sharp well done.</td>', 'LOL, did you kill this bug for the purpose of this shot?  Poor thing :  ).   Very clear and sharp well done.', '2003-09-09 12:55:33.000000', NULL, 1),
(413466, 36700, 7969, '<td valign="top">You have (almost) managed to make him look cute, but he is a bug :  ).  very well done.</td>', 'You have (almost) managed to make him look cute, but he is a bug :  ).  very well done.', '2003-09-09 12:56:25.000000', NULL, 1),
(413468, 36776, 7969, '<td valign="top">Creative approach, very clever.</td>', 'Creative approach, very clever.', '2003-09-09 12:57:42.000000', NULL, 1),
(413469, 36742, 7969, '<td valign="top">I like the solitary drop of water.</td>', 'I like the solitary drop of water.', '2003-09-09 12:58:24.000000', NULL, 1),
(413470, 36292, 11793, '<td valign="top">very nice</td>', 'very nice', '2003-09-09 12:59:36.000000', NULL, 1),
(413472, 36824, 7969, '<td valign="top">What I really like about your shot is the soft periwinkle color that surrounds your shy bug, tho i do wish we could see more of him, he looks like a unique critter.</td>', 'What I really like about your shot is the soft periwinkle color that surrounds your shy bug, tho i do wish we could see more of him, he looks like a unique critter.', '2003-09-09 12:59:56.000000', NULL, 1),
(413474, 36866, 7969, '<td valign="top">The black and white tones have a very  good range in your shot, but I think dragon flies tend to be very colorful and I think I wish I could see his colors.  Good clear image tho. The leaf composition and depth of field are very well done.</td>', 'The black and white tones have a very  good range in your shot, but I think dragon flies tend to be very colorful and I think I wish I could see his colors.  Good clear image tho. The leaf composition and depth of field are very well done.', '2003-09-09 13:02:18.000000', NULL, 1),
(413475, 36530, 9452, '<td valign="top">Nice macro, but unfocused</td>', 'Nice macro, but unfocused', '2003-09-09 13:02:24.000000', NULL, 1),
(413478, 36459, 7969, '<td valign="top">You caught the transparent wings well.</td>', 'You caught the transparent wings well.', '2003-09-09 13:03:46.000000', NULL, 1),
(413480, 36296, 9452, '<td valign="top">Just excellent!, nice, my favorite so far 10</td>', 'Just excellent!, nice, my favorite so far 10', '2003-09-09 13:04:22.000000', NULL, 1),
(413483, 36754, 7969, '<td valign="top">Sharp, clear image very well done, good composition too.</td>', 'Sharp, clear image very well done, good composition too.', '2003-09-09 13:05:42.000000', NULL, 1),
(413485, 36020, 7969, '<td valign="top">WO! COOL eyes, and oddly they do look friendly :  ). Did you have a good lense or were you just that close? Great color, good work.</td>', 'WO! COOL eyes, and oddly they do look friendly :  ). Did you have a good lense or were you just that close? Great color, good work.', '2003-09-09 13:06:00.000000', NULL, 1),
(413486, 36470, 7969, '<td valign="top">Lovely shot,  very well done, my only sort of suggestion (which I could not accomplish with my shot either)  was to have less \''space\'' behind him, giving him more room to \''fly\'' into.</td>', 'Lovely shot,  very well done, my only sort of suggestion (which I could not accomplish with my shot either)  was to have less \''space\'' behind him, giving him more room to \''fly\'' into.', '2003-09-09 13:06:24.000000', NULL, 1),
(413487, 36785, 7969, '<td valign="top">I like that the edge of the leaf and the body of the dragonfly are the same color, I also like the position of his wings. Good job.</td>', 'I like that the edge of the leaf and the body of the dragonfly are the same color, I also like the position of his wings. Good job.', '2003-09-09 13:06:44.000000', NULL, 1),
(413490, 36879, 9452, '<td valign="top">out of focus, :(</td>', 'out of focus, :(', '2003-09-09 13:08:58.000000', NULL, 1),
(413493, 36884, 7190, '<td valign="top">love it</td>', 'love it', '2003-09-09 13:16:58.000000', NULL, 1),
(413496, 36154, 6668, '<td valign="top">Looks a little out of focus.</td>', 'Looks a little out of focus.', '2003-09-09 13:19:34.000000', NULL, 1),
(413497, 36662, 6668, '<td valign="top">I find the one dark blade of grass that is blocking his face a little distracting, otherwise nice shot.</td>', 'I find the one dark blade of grass that is blocking his face a little distracting, otherwise nice shot.', '2003-09-09 13:21:18.000000', NULL, 1),
(413498, 36818, 6668, '<td valign="top">I would have cropped the bottom a little, just a little to much web for me,  I like the black in the background, gives it kind of a spooky look.</td>', 'I would have cropped the bottom a little, just a little to much web for me,  I like the black in the background, gives it kind of a spooky look.', '2003-09-09 13:23:18.000000', NULL, 1),
(413500, 36779, 6668, '<td valign="top">I like this shot, very nice detail, I like his cute little beady eyes. :-)</td>', 'I like this shot, very nice detail, I like his cute little beady eyes. :-)', '2003-09-09 13:26:44.000000', NULL, 1),
(413543, 36850, 2883, '<td valign="top">I like the coloring. The wing gives the photo character.</td>', 'I like the coloring. The wing gives the photo character.', '2003-09-09 14:49:55.000000', NULL, 1),
(413544, 36846, 2883, '<td valign="top">This is a good composition. The blurred background is a little overpowering.</td>', 'This is a good composition. The blurred background is a little overpowering.', '2003-09-09 14:51:08.000000', NULL, 1),
(413545, 36177, 2883, '<td valign="top">Great composition and use of humor. I like the blue, but teh insect is a little dark.</td>', 'Great composition and use of humor. I like the blue, but teh insect is a little dark.', '2003-09-09 14:51:49.000000', NULL, 1),
(413546, 36780, 2883, '<td valign="top">Great coloring and clarity in this photo. It might be a little better if the camera was angled such that the blurred flower in the foreground was out of view and there was less green in the background at the top.</td>', 'Great coloring and clarity in this photo. It might be a little better if the camera was angled such that the blurred flower in the foreground was out of view and there was less green in the background at the top.', '2003-09-09 14:53:03.000000', NULL, 1),
(413547, 36086, 2883, '<td valign="top">I like the cropping to bring attention to the insect, but I think it just needs a little less on the left side. Great detail.</td>', 'I like the cropping to bring attention to the insect, but I think it just needs a little less on the left side. Great detail.', '2003-09-09 14:53:59.000000', NULL, 1),
(413549, 36471, 2883, '<td valign="top">I think ''I''ve Fallen and I Can''t Get Up!'' would be a good title for this. ;) I like the composition, but I think the colors could be enhanced a bit. Good focus no the insect.</td>', 'I think ''I''ve Fallen and I Can''t Get Up!'' would be a good title for this. ;) I like the composition, but I think the colors could be enhanced a bit. Good focus no the insect.', '2003-09-09 14:55:10.000000', NULL, 1),
(413552, 36410, 2883, '<td valign="top">I think the background kind of dulls the overall picture. It might be better with a little more flower shown on the left side. I''m not going to ask how you know it''s name!</td>', 'I think the background kind of dulls the overall picture. It might be better with a little more flower shown on the left side. I''m not going to ask how you know it''s name!', '2003-09-09 14:56:34.000000', NULL, 1),
(413554, 36754, 2883, '<td valign="top">Nice composition. I really like the use of a white background .</td>', 'Nice composition. I really like the use of a white background .', '2003-09-09 14:57:28.000000', NULL, 1),
(413556, 36678, 2883, '<td valign="top">Good idea. It would be better if the focus at the insects level was clearer and if the lighting wasn''t so strong. I like the humor though.</td>', 'Good idea. It would be better if the focus at the insects level was clearer and if the lighting wasn''t so strong. I like the humor though.', '2003-09-09 14:58:23.000000', NULL, 1),
(413558, 36779, 2883, '<td valign="top">Great close-up of the spider. The red takes away from the picture, however, since it draws the eye.</td>', 'Great close-up of the spider. The red takes away from the picture, however, since it draws the eye.', '2003-09-09 14:59:16.000000', NULL, 1),
(413559, 36876, 2883, '<td valign="top">Good close-up with a wonderful use of lighting.</td>', 'Good close-up with a wonderful use of lighting.', '2003-09-09 14:59:51.000000', NULL, 1),
(413560, 36681, 2883, '<td valign="top">This is a nice looking butterfly. The photo is a little grainy and dark.</td>', 'This is a nice looking butterfly. The photo is a little grainy and dark.', '2003-09-09 15:00:43.000000', NULL, 1),
(413561, 36203, 2883, '<td valign="top">Nice use of the title. The overall color could be a little more enhanced.</td>', 'Nice use of the title. The overall color could be a little more enhanced.', '2003-09-09 15:01:41.000000', NULL, 1),
(413562, 36247, 2883, '<td valign="top">Nice DOF, though I think the moth could be a little sharper.</td>', 'Nice DOF, though I think the moth could be a little sharper.', '2003-09-09 15:02:46.000000', NULL, 1),
(413563, 36873, 2883, '<td valign="top">Wonderful idea and great use of contrasting color. Good composition as well.</td>', 'Wonderful idea and great use of contrasting color. Good composition as well.', '2003-09-09 15:04:27.000000', NULL, 1),
(413564, 36185, 2883, '<td valign="top">This is a nice picture of a mantis. The background could be improved so it doesn''t blend in as much.</td>', 'This is a nice picture of a mantis. The background could be improved so it doesn''t blend in as much.', '2003-09-09 15:05:24.000000', NULL, 1),
(413565, 36527, 6870, '<td valign="top">The wings are so fascinating--have you considered cropping out the body and just using the wings?</td>', 'The wings are so fascinating--have you considered cropping out the body and just using the wings?', '2003-09-09 15:05:53.000000', NULL, 1),
(413567, 36448, 2883, '<td valign="top">This is a good idea, but the overwhelming brownish shades makes it difficult to make out what is suppose to be the subject of the photo.</td>', 'This is a good idea, but the overwhelming brownish shades makes it difficult to make out what is suppose to be the subject of the photo.', '2003-09-09 15:08:07.000000', NULL, 1),
(413568, 36884, 2883, '<td valign="top">I like the contrasts and the clarity. I also like the emotional value this photo gives, which helps it towards the ''intimate'' part of the challenge so many are missing.</td>', 'I like the contrasts and the clarity. I also like the emotional value this photo gives, which helps it towards the ''intimate'' part of the challenge so many are missing.', '2003-09-09 15:13:10.000000', NULL, 1),
(413571, 36471, 6870, '<td valign="top">A Jerusalem Cricket. Creepy. I found one in my shoe once when I was camping. Nice composition and lighting. Perhaps could use a bit o'' contrast and color saturation. Nice.</td>', 'A Jerusalem Cricket. Creepy. I found one in my shoe once when I was camping. Nice composition and lighting. Perhaps could use a bit o'' contrast and color saturation. Nice.', '2003-09-09 15:22:35.000000', NULL, 1),
(413582, 36846, 1280, '<td valign="top">Nice detail on the wings especially.  Good picture, well done. :-)</td>', 'Nice detail on the wings especially.  Good picture, well done. :-)', '2003-09-09 15:50:13.000000', NULL, 1),
(413583, 36446, 1280, '<td valign="top">Good colour,  and diagonal comp. Dof could be better on the face.</td>', 'Good colour,  and diagonal comp. Dof could be better on the face.', '2003-09-09 15:53:01.000000', NULL, 1),
(413585, 36604, 1280, '<td valign="top">Good job!</td>', 'Good job!', '2003-09-09 15:53:45.000000', NULL, 1),
(413586, 36629, 1280, '<td valign="top">Nice!  I like the colors.</td>', 'Nice!  I like the colors.', '2003-09-09 15:54:35.000000', NULL, 1),
(413587, 36745, 1280, '<td valign="top">Good detail.  I''d prefer to see the front of the spider.  Actually that''s why I didn''t submit my spider pic.  <br/>You did a good job though.  7</td>', 'Good detail.  I''d prefer to see the front of the spider.  Actually that''s why I didn''t submit my spider pic.  You did a good job though.  7', '2003-09-09 15:56:39.000000', NULL, 1),
(413588, 36779, 1280, '<td valign="top">Very good detail.  The red bg helps it stand out too.</td>', 'Very good detail.  The red bg helps it stand out too.', '2003-09-09 15:57:56.000000', NULL, 1),
(413589, 36880, 1280, '<td valign="top">Pretty colours, and good dof.  The texture of the thistle also adds interest.  Good job.</td>', 'Pretty colours, and good dof.  The texture of the thistle also adds interest.  Good job.', '2003-09-09 16:05:18.000000', NULL, 1),
(413591, 36851, 1280, '<td valign="top">Nice.  The dark bg helps this Praying Mantis stand out. Focus is a wee bit soft, nevertheless a good job!</td>', 'Nice.  The dark bg helps this Praying Mantis stand out. Focus is a wee bit soft, nevertheless a good job!', '2003-09-09 16:06:58.000000', NULL, 1),
(413592, 36872, 10084, '<td valign="top">Nice focus. Beautiful composition. Colors are really brought out in this shot.  The shade of purple are really good. Frame works perfect with the piece.</td>', 'Nice focus. Beautiful composition. Colors are really brought out in this shot.  The shade of purple are really good. Frame works perfect with the piece.', '2003-09-09 16:07:36.000000', NULL, 1),
(413593, 36826, 1280, '<td valign="top">Enchanting colouring and good silhouette.</td>', 'Enchanting colouring and good silhouette.', '2003-09-09 16:07:56.000000', NULL, 1),
(413594, 36816, 1280, '<td valign="top">Good one!</td>', 'Good one!', '2003-09-09 16:09:15.000000', NULL, 1),
(413595, 36292, 10084, '<td valign="top">Beautiful focus. Great depth of field. Composition is really good.  The frame works great with the shot.</td>', 'Beautiful focus. Great depth of field. Composition is really good.  The frame works great with the shot.', '2003-09-09 16:09:51.000000', NULL, 1),
(413596, 36557, 10084, '<td valign="top">Great depth of field gives the shot a beautiful composition. You were able to capture some nice reflections that brings the grasshopper alive.</td>', 'Great depth of field gives the shot a beautiful composition. You were able to capture some nice reflections that brings the grasshopper alive.', '2003-09-09 16:11:43.000000', NULL, 1),
(413597, 36317, 10084, '<td valign="top">Great composition makes the piece very dynamic and brings the subject alive. Depth of field is really good. Focusing is spot on.  Beautiful shot.</td>', 'Great composition makes the piece very dynamic and brings the subject alive. Depth of field is really good. Focusing is spot on.  Beautiful shot.', '2003-09-09 16:13:01.000000', NULL, 1),
(413600, 36851, 10084, '<td valign="top">Great colors. The lighting is great. Love the shadows and reflections. The darker background really brings the insects alive and make them pop out of the shot. Don''t know how you got the mantis to look at the camera.</td>', 'Great colors. The lighting is great. Love the shadows and reflections. The darker background really brings the insects alive and make them pop out of the shot. Don''t know how you got the mantis to look at the camera.', '2003-09-09 16:23:47.000000', NULL, 1),
(413601, 36866, 10084, '<td valign="top">Great focus makes the composition so much better. The field of depth really brings the insect alive. Beautiful reflections.</td>', 'Great focus makes the composition so much better. The field of depth really brings the insect alive. Beautiful reflections.', '2003-09-09 16:25:27.000000', NULL, 1),
(413606, 36604, 10705, '<td valign="top">Incredible detail ... very nice composition.</td>', 'Incredible detail ... very nice composition.', '2003-09-09 16:37:18.000000', NULL, 1),
(413618, 36037, 6667, '<td valign="top">What? No sheets?</td>', 'What? No sheets?', '2003-09-09 17:06:09.000000', NULL, 1),
(413624, 36758, 6667, '<td valign="top">DOF fades on right</td>', 'DOF fades on right', '2003-09-09 17:19:55.000000', NULL, 1),
(413625, 36780, 6667, '<td valign="top">DOF and Sharpness takes away from a greatshot.</td>', 'DOF and Sharpness takes away from a greatshot.', '2003-09-09 17:22:25.000000', NULL, 1),
(413628, 36605, 6667, '<td valign="top">Focus on insect would have made this a great, great capture.</td>', 'Focus on insect would have made this a great, great capture.', '2003-09-09 17:24:15.000000', NULL, 1),
(413629, 36877, 6667, '<td valign="top">Focus  on insect need to be sharper.</td>', 'Focus  on insect need to be sharper.', '2003-09-09 17:26:30.000000', NULL, 1),
(413630, 36874, 6667, '<td valign="top">Over exposed but great capture.</td>', 'Over exposed but great capture.', '2003-09-09 17:29:09.000000', NULL, 1),
(413631, 36340, 6667, '<td valign="top">Sharpness</td>', 'Sharpness', '2003-09-09 17:30:35.000000', NULL, 1),
(413633, 36818, 10084, '<td valign="top">Great composition.  Amazing picture of a spider. I like how the bottom of the picture is bright and the hole that its coming out of is really dark. Focusing is really good. Great to see the hairyness of it.</td>', 'Great composition.  Amazing picture of a spider. I like how the bottom of the picture is bright and the hole that its coming out of is really dark. Focusing is really good. Great to see the hairyness of it.', '2003-09-09 17:32:12.000000', NULL, 1),
(413635, 36364, 10084, '<td valign="top">Beautiful macro. Composition is really good. Love the reflections of the droplets of water. Love the colors you captured. The design of the body on this spider is so beautiful. Great capture.</td>', 'Beautiful macro. Composition is really good. Love the reflections of the droplets of water. Love the colors you captured. The design of the body on this spider is so beautiful. Great capture.', '2003-09-09 17:34:05.000000', NULL, 1),
