(415163, 36826, 11283, '<td valign="top">Now that is cool.</td>', 'Now that is cool.', '2003-09-10 20:13:36.000000', NULL, 1),
(415165, 36470, 11283, '<td valign="top">Very crisp focus. Nice.</td>', 'Very crisp focus. Nice.', '2003-09-10 20:14:15.000000', NULL, 1),
(415168, 36756, 11283, '<td valign="top">Cool shot. Looks like mothra.</td>', 'Cool shot. Looks like mothra.', '2003-09-10 20:17:30.000000', NULL, 1),
(415206, 36607, 11283, '<td valign="top">Awesome shot just a but fuzzy. Must have been a tough one.</td>', 'Awesome shot just a but fuzzy. Must have been a tough one.', '2003-09-10 21:05:28.000000', NULL, 1),
(415240, 36049, 2883, '<td valign="top">I like the coloring and lighting. Good composition.</td>', 'I like the coloring and lighting. Good composition.', '2003-09-10 21:47:35.000000', NULL, 1),
(415241, 36826, 2883, '<td valign="top">This is a very interesting approach. The green adds to the creepiness. I think it would be a little better is the bright spot of the light wasn''t noticeble.</td>', 'This is a very interesting approach. The green adds to the creepiness. I think it would be a little better is the bright spot of the light wasn''t noticeble.', '2003-09-10 21:48:52.000000', NULL, 1),
(415243, 36802, 2883, '<td valign="top">Too bad the one wasp is obscurring the view from the hole. This makes the other wasp and the subject of the photo difficult to see.</td>', 'Too bad the one wasp is obscurring the view from the hole. This makes the other wasp and the subject of the photo difficult to see.', '2003-09-10 21:50:34.000000', NULL, 1),
(415245, 36763, 2883, '<td valign="top">Good use of splitting the screen with color. There''s a little bit of graininess to the left upper side of the photo. I could see the colors on the insect enhanced a bit.</td>', 'Good use of splitting the screen with color. There''s a little bit of graininess to the left upper side of the photo. I could see the colors on the insect enhanced a bit.', '2003-09-10 21:51:37.000000', NULL, 1),
(415246, 36872, 2883, '<td valign="top">Wonderful coloring on a dark background. That is one proud looking insect.</td>', 'Wonderful coloring on a dark background. That is one proud looking insect.', '2003-09-10 21:52:21.000000', NULL, 1),
(415248, 36784, 2883, '<td valign="top">Nice coloring and composition. I also like the lighting through the moth''s wing.</td>', 'Nice coloring and composition. I also like the lighting through the moth''s wing.', '2003-09-10 21:53:31.000000', NULL, 1),
(415249, 36871, 2883, '<td valign="top">Good DOF and sharpness. There''s a little graininess in the background.</td>', 'Good DOF and sharpness. There''s a little graininess in the background.', '2003-09-10 21:54:18.000000', NULL, 1),
(415251, 36529, 2883, '<td valign="top">Good pose to catch and nice composition.</td>', 'Good pose to catch and nice composition.', '2003-09-10 21:55:56.000000', NULL, 1),
(415252, 36725, 2883, '<td valign="top">The contrast could be better and the angle could be such that the spider is more visible in the web.</td>', 'The contrast could be better and the angle could be such that the spider is more visible in the web.', '2003-09-10 21:58:06.000000', NULL, 1),
(415253, 36242, 2883, '<td valign="top">I like the use of the deep black background and the catchy title. The lighting is a little intense.</td>', 'I like the use of the deep black background and the catchy title. The lighting is a little intense.', '2003-09-10 21:58:57.000000', NULL, 1),
(415256, 36778, 2883, '<td valign="top">I like colors, though I think they could brought out a little more. Good angle and lighting.</td>', 'I like colors, though I think they could brought out a little more. Good angle and lighting.', '2003-09-10 22:01:55.000000', NULL, 1),
(415258, 36874, 2883, '<td valign="top">The lighting is a little bright for the whit background, but its a great composition.</td>', 'The lighting is a little bright for the whit background, but its a great composition.', '2003-09-10 22:02:31.000000', NULL, 1),
(415260, 36301, 2883, '<td valign="top">The overall picture is a little fuzzy and the colors and contrasts could be brought out a bit. I think a little less cropping would also help.</td>', 'The overall picture is a little fuzzy and the colors and contrasts could be brought out a bit. I think a little less cropping would also help.', '2003-09-10 22:03:18.000000', NULL, 1),
(415262, 36841, 2883, '<td valign="top">Great use of the leaf in this photo. I''m not sure what the red spot in the middle of the photo is, but I''m not going to take off for it. Very amusing.</td>', 'Great use of the leaf in this photo. I''m not sure what the red spot in the middle of the photo is, but I''m not going to take off for it. Very amusing.', '2003-09-10 22:04:27.000000', NULL, 1),
(415264, 36696, 2883, '<td valign="top">Nice alien-like look to it with the lighting. It might be better cropped off a little on the left side. The light reflection in the eye adds a little bit of an evil look to it.</td>', 'Nice alien-like look to it with the lighting. It might be better cropped off a little on the left side. The light reflection in the eye adds a little bit of an evil look to it.', '2003-09-10 22:05:44.000000', NULL, 1),
(415266, 36575, 2883, '<td valign="top">Good close-up, though the colors are a little bland. The background is grainy and could use some cleaning up.</td>', 'Good close-up, though the colors are a little bland. The background is grainy and could use some cleaning up.', '2003-09-10 22:06:32.000000', NULL, 1),
(415267, 36803, 2883, '<td valign="top">Ouch! Good idea. The lighting is a little distracting. Good composition.</td>', 'Ouch! Good idea. The lighting is a little distracting. Good composition.', '2003-09-10 22:07:24.000000', NULL, 1),
(415268, 36364, 2883, '<td valign="top">Nice close-up. The reflected light from the flash is distracting though.</td>', 'Nice close-up. The reflected light from the flash is distracting though.', '2003-09-10 22:08:11.000000', NULL, 1),
(415269, 36317, 2883, '<td valign="top">Good pose. The background is a little too bright and takes away from the blue eyes.</td>', 'Good pose. The background is a little too bright and takes away from the blue eyes.', '2003-09-10 22:08:51.000000', NULL, 1),
(415270, 36843, 2883, '<td valign="top">I think this photo would have a better feel to it if it were rotated counter-clokwise 90 degrees. Good close-up.</td>', 'I think this photo would have a better feel to it if it were rotated counter-clokwise 90 degrees. Good close-up.', '2003-09-10 22:09:54.000000', NULL, 1),
(415273, 36809, 2883, '<td valign="top">I love the soft lighting and overall soft feel to this photo. Great composition. It might be better with the colors in the insect enhanced a bit, but overall a wonderful photo.</td>', 'I love the soft lighting and overall soft feel to this photo. Great composition. It might be better with the colors in the insect enhanced a bit, but overall a wonderful photo.', '2003-09-10 22:11:04.000000', NULL, 1),
(415274, 36558, 2883, '<td valign="top">Nice DOF and sharpness of the insect. Good lighting and colors.</td>', 'Nice DOF and sharpness of the insect. Good lighting and colors.', '2003-09-10 22:11:41.000000', NULL, 1),
(415276, 36726, 2883, '<td valign="top">Great facial expression (both the bee and the person). Good close-up, though it might be better if the eyes were slightly out of focus to emphasize the bee. Great idea.</td>', 'Great facial expression (both the bee and the person). Good close-up, though it might be better if the eyes were slightly out of focus to emphasize the bee. Great idea.', '2003-09-10 22:12:44.000000', NULL, 1),
(415278, 36815, 2883, '<td valign="top">The contrast could be a little better. The insect blends in with the rest of the photo a little too much.</td>', 'The contrast could be a little better. The insect blends in with the rest of the photo a little too much.', '2003-09-10 22:13:29.000000', NULL, 1),
(415281, 36877, 2883, '<td valign="top">Nice capture. I like the coloring and lighting.</td>', 'Nice capture. I like the coloring and lighting.', '2003-09-10 22:14:03.000000', NULL, 1),
(415283, 36607, 2883, '<td valign="top">Good battle scene. The focus could be a little clearer and the colors enhanced a bit.</td>', 'Good battle scene. The focus could be a little clearer and the colors enhanced a bit.', '2003-09-10 22:14:47.000000', NULL, 1),
(415284, 36742, 2883, '<td valign="top">Nice sharp focus on the insect.  It might be better if it was cropped a little more.</td>', 'Nice sharp focus on the insect.  It might be better if it was cropped a little more.', '2003-09-10 22:16:01.000000', NULL, 1),
(415285, 36191, 2883, '<td valign="top">Nice color contrast with the background. The colors could be enhanced a bit.</td>', 'Nice color contrast with the background. The colors could be enhanced a bit.', '2003-09-10 22:16:41.000000', NULL, 1),
(415287, 36449, 2883, '<td valign="top">Great use of colors and nice, sharp focus on the insect. The blurred flowers in the background emphasize the insect.</td>', 'Great use of colors and nice, sharp focus on the insect. The blurred flowers in the background emphasize the insect.', '2003-09-10 22:17:35.000000', NULL, 1),
(415290, 36407, 2883, '<td valign="top">Good coloring, though they could be enhanced and the contrasts increased a bit.</td>', 'Good coloring, though they could be enhanced and the contrasts increased a bit.', '2003-09-10 22:18:05.000000', NULL, 1),
(415297, 36287, 4793, '<td valign="top">Nice Colors, how did you get this one to stay put for the photo?</td>', 'Nice Colors, how did you get this one to stay put for the photo?', '2003-09-10 22:24:01.000000', NULL, 1),
(415301, 36529, 4793, '<td valign="top">A very nice photo, nice colors</td>', 'A very nice photo, nice colors', '2003-09-10 22:28:21.000000', NULL, 1),
(415303, 36296, 4793, '<td valign="top">Very nice, colors and composition</td>', 'Very nice, colors and composition', '2003-09-10 22:29:17.000000', NULL, 1),
(415308, 36756, 4793, '<td valign="top">This is bug ugly at it''s best, good capture</td>', 'This is bug ugly at it''s best, good capture', '2003-09-10 22:30:42.000000', NULL, 1),
(415312, 36871, 4793, '<td valign="top">very nice</td>', 'very nice', '2003-09-10 22:32:46.000000', NULL, 1),
(415315, 36780, 4793, '<td valign="top">Very nice</td>', 'Very nice', '2003-09-10 22:34:18.000000', NULL, 1),
(415319, 36429, 4793, '<td valign="top">Beautiful shot</td>', 'Beautiful shot', '2003-09-10 22:39:16.000000', NULL, 1),
