(415394, 36823, 11283, '<td valign="top">Very nice photo. Love the crispness of it.</td>', 'Very nice photo. Love the crispness of it.', '2003-09-10 23:47:36.000000', NULL, 1),
(415395, 36775, 11283, '<td valign="top">Nice framing and color. Looks like it just came in for a landing.</td>', 'Nice framing and color. Looks like it just came in for a landing.', '2003-09-10 23:49:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(415447, 36446, 4793, '<td valign="top">Neat idea, very nice colors</td>', 'Neat idea, very nice colors', '2003-09-11 01:11:48.000000', NULL, 1),
(415448, 36690, 4793, '<td valign="top">Very nice colors and composition</td>', 'Very nice colors and composition', '2003-09-11 01:13:11.000000', NULL, 1),
(415454, 36575, 4793, '<td valign="top">Congrats on getting him to stay still to take the photo, I like him on the stump</td>', 'Congrats on getting him to stay still to take the photo, I like him on the stump', '2003-09-11 01:16:34.000000', NULL, 1),
(415456, 36292, 4793, '<td valign="top">I like your comp and colors, very nice shot</td>', 'I like your comp and colors, very nice shot', '2003-09-11 01:17:39.000000', NULL, 1),
(415457, 36775, 4793, '<td valign="top">Beautiful colors and comp.</td>', 'Beautiful colors and comp.', '2003-09-11 01:19:35.000000', NULL, 1),
(415462, 36483, 4793, '<td valign="top">I love your colors</td>', 'I love your colors', '2003-09-11 01:22:21.000000', NULL, 1),
(415467, 36829, 4793, '<td valign="top">Very nice</td>', 'Very nice', '2003-09-11 01:23:55.000000', NULL, 1),
(415512, 36775, 7350, '<td valign="top">One of the best butterfly shots I''ve ever seen.  On this one, you get the expression on his face... A 10 from me.</td>', 'One of the best butterfly shots I''ve ever seen.  On this one, you get the expression on his face... A 10 from me.', '2003-09-11 01:52:47.000000', NULL, 1),
(415515, 36802, 7350, '<td valign="top">Weird how their stinger is sort of shaped like a motorcycle tailpipe. 10.</td>', 'Weird how their stinger is sort of shaped like a motorcycle tailpipe. 10.', '2003-09-11 01:55:51.000000', NULL, 1),
(415518, 36873, 2310, '<td valign="top">I love the bright colors!  I do find that glare on the beetle''s crapace to be a little distracting.  I wonder if you could have filtered the light somehow (tissue screen?) and still maintained those intense hues...</td>', 'I love the bright colors!  I do find that glare on the beetle''s crapace to be a little distracting.  I wonder if you could have filtered the light somehow (tissue screen?) and still maintained those intense hues...', '2003-09-11 02:07:09.000000', NULL, 1),
(415520, 36700, 2310, '<td valign="top">I like the angle you achieved here.  I might find it more appealing if you were to try to crop out the darker parts of the leaf on the bottom and bottom right.  It also seems that the main focus is just behind the head and I would like to see the head and eyes a little sharper.  Otherwise this is a great composition...</td>', 'I like the angle you achieved here.  I might find it more appealing if you were to try to crop out the darker parts of the leaf on the bottom and bottom right.  It also seems that the main focus is just behind the head and I would like to see the head and eyes a little sharper.  Otherwise this is a great composition...', '2003-09-11 02:09:53.000000', NULL, 1),
(415522, 36687, 2310, '<td valign="top">This would be a ribbon if only the depth of field were a little bigger and more of the butterfly was in focus, particularly the head...</td>', 'This would be a ribbon if only the depth of field were a little bigger and more of the butterfly was in focus, particularly the head...', '2003-09-11 02:12:24.000000', NULL, 1),
(415524, 36832, 2310, '<td valign="top">Definitely my favorite so far...Excellent focus and I love the composition and the great use of color...the only thing that kind of "bugs" me is that it seems a little bottom heavy with all that intense orange down there...not sure what to do to improve that...</td>', 'Definitely my favorite so far...Excellent focus and I love the composition and the great use of color...the only thing that kind of "bugs" me is that it seems a little bottom heavy with all that intense orange down there...not sure what to do to improve that...', '2003-09-11 02:15:21.000000', NULL, 1),
(415527, 36785, 2310, '<td valign="top">What a cool shot!  Great focus and composition.  I do find the reflections in the eyes to be a little distracting and (I can''t believe I am saying this) the color almost seems too intense.  Not sure if a polarizing filter or a screen would help reduce the glare...That thing is unreal!</td>', 'What a cool shot!  Great focus and composition.  I do find the reflections in the eyes to be a little distracting and (I can''t believe I am saying this) the color almost seems too intense.  Not sure if a polarizing filter or a screen would help reduce the glare...That thing is unreal!', '2003-09-11 02:18:28.000000', NULL, 1),
(415529, 36635, 2310, '<td valign="top">This would have been one of my top picks...if only that pesky leaf in the foreground on the left wasn''t there!  There are some things that are just really hard to control when photographing wildlife...</td>', 'This would have been one of my top picks...if only that pesky leaf in the foreground on the left wasn''t there!  There are some things that are just really hard to control when photographing wildlife...', '2003-09-11 02:23:38.000000', NULL, 1),
(415549, 36477, 8843, '<td valign="top">oh my goodness what are they resting on! :P</td>', 'oh my goodness what are they resting on! :P', '2003-09-11 03:02:11.000000', NULL, 1),
(415560, 36429, 11078, '<td valign="top">Excellent work</td>', 'Excellent work', '2003-09-11 03:38:35.000000', NULL, 1),
(415569, 36547, 11078, '<td valign="top">What a character</td>', 'What a character', '2003-09-11 03:53:38.000000', NULL, 1),
(415600, 36572, 3554, '<td valign="top">I love the brown on green. Nice capture. Bottom left part of the wing is a little soft.</td>', 'I love the brown on green. Nice capture. Bottom left part of the wing is a little soft.', '2003-09-11 05:06:35.000000', NULL, 1),
(415601, 36871, 3554, '<td valign="top">Great clarity. I love the "eye"</td>', 'Great clarity. I love the "eye"', '2003-09-11 05:07:41.000000', NULL, 1),
(415602, 36843, 3554, '<td valign="top">Definitely the most unusual looking insects in the challenge!</td>', 'Definitely the most unusual looking insects in the challenge!', '2003-09-11 05:08:33.000000', NULL, 1),
(415603, 36872, 3554, '<td valign="top">I like the combination of colors, the purple flower contrasts nicely with the yellow butterfly (moth?).</td>', 'I like the combination of colors, the purple flower contrasts nicely with the yellow butterfly (moth?).', '2003-09-11 05:09:39.000000', NULL, 1),
(415604, 36809, 3554, '<td valign="top">Wonderful soft feel to this one.</td>', 'Wonderful soft feel to this one.', '2003-09-11 05:10:08.000000', NULL, 1),
(415605, 36774, 3554, '<td valign="top">I love the composition but the whole thing feels out of focus.</td>', 'I love the composition but the whole thing feels out of focus.', '2003-09-11 05:11:02.000000', NULL, 1),
(415696, 36687, 2883, '<td valign="top">Great captured pose. The colors could be brought out a bit and the focus is a little fuzzy.</td>', 'Great captured pose. The colors could be brought out a bit and the focus is a little fuzzy.', '2003-09-11 10:12:00.000000', NULL, 1),
(415697, 36169, 2883, '<td valign="top">Good coloring and lighting. I think it could use a little less cropping on top.</td>', 'Good coloring and lighting. I think it could use a little less cropping on top.', '2003-09-11 10:12:53.000000', NULL, 1),
(415699, 36296, 2883, '<td valign="top">Good use of DOF. The colors seem a little bland and could be enhanced a bit.</td>', 'Good use of DOF. The colors seem a little bland and could be enhanced a bit.', '2003-09-11 10:13:39.000000', NULL, 1),
(415700, 36459, 2883, '<td valign="top">Great detail and composition. I like the title as well.</td>', 'Great detail and composition. I like the title as well.', '2003-09-11 10:14:26.000000', NULL, 1),
(415701, 36879, 2883, '<td valign="top">This wold be a great photo if the blue was brought out more and it was sharper.</td>', 'This wold be a great photo if the blue was brought out more and it was sharper.', '2003-09-11 10:15:14.000000', NULL, 1),
(415702, 36804, 2883, '<td valign="top">Very humorous. The contrasts could be enhanced a bit, but the composition is good.</td>', 'Very humorous. The contrasts could be enhanced a bit, but the composition is good.', '2003-09-11 10:16:12.000000', NULL, 1),
(415704, 36020, 2883, '<td valign="top">Wonderful coloring and expression. Very good DOF and composition.</td>', 'Wonderful coloring and expression. Very good DOF and composition.', '2003-09-11 10:16:53.000000', NULL, 1),
(415706, 36767, 2883, '<td valign="top">The photo is just too fuzzy. It looks like the button was accidentally pushed. Good idea though.</td>', 'The photo is just too fuzzy. It looks like the button was accidentally pushed. Good idea though.', '2003-09-11 10:17:55.000000', NULL, 1),
(415707, 36800, 2883, '<td valign="top">I think just showing the engraved wood would have fit the title better.</td>', 'I think just showing the engraved wood would have fit the title better.', '2003-09-11 10:18:39.000000', NULL, 1),
(415708, 36867, 2883, '<td valign="top">Nice coloring and composition.</td>', 'Nice coloring and composition.', '2003-09-11 10:19:09.000000', NULL, 1),
(415710, 36477, 2883, '<td valign="top">This might be a better photo if the top and right sides were cropped just past the last ladybug to show less of the sands. The colors could be enhanced as well.</td>', 'This might be a better photo if the top and right sides were cropped just past the last ladybug to show less of the sands. The colors could be enhanced as well.', '2003-09-11 10:23:09.000000', NULL, 1),
(415713, 36605, 2883, '<td valign="top">Nice lighting and pose. The background is a little distracting.</td>', 'Nice lighting and pose. The background is a little distracting.', '2003-09-11 10:23:43.000000', NULL, 1),
(415714, 36881, 2883, '<td valign="top">Good closeup. The right tree could be cropped out of the picture to enhance the contrast between the green background and the moth.</td>', 'Good closeup. The right tree could be cropped out of the picture to enhance the contrast between the green background and the moth.', '2003-09-11 10:24:39.000000', NULL, 1),
(415715, 36756, 2883, '<td valign="top">Nice interaction with the insect. The focus is great, but the coloring is a little dull, which may be emphasized by the dull green border.</td>', 'Nice interaction with the insect. The focus is great, but the coloring is a little dull, which may be emphasized by the dull green border.', '2003-09-11 10:25:43.000000', NULL, 1),
(415716, 36604, 2883, '<td valign="top">It''s a decent attempt, but the lighting reflecting off the insect is a little distracting.</td>', 'It''s a decent attempt, but the lighting reflecting off the insect is a little distracting.', '2003-09-11 10:26:24.000000', NULL, 1),
(415717, 36821, 2883, '<td valign="top">Good use of the title to bring expression to the insect. The color is a little dull, but the photo is very clear.</td>', 'Good use of the title to bring expression to the insect. The color is a little dull, but the photo is very clear.', '2003-09-11 10:27:14.000000', NULL, 1),
(415718, 36774, 2883, '<td valign="top">Good attempt. The contrasts could be enhanced and it''s a little fuzzy.</td>', 'Good attempt. The contrasts could be enhanced and it''s a little fuzzy.', '2003-09-11 10:28:01.000000', NULL, 1),
(415719, 36192, 2883, '<td valign="top">The overall photo is a little hazy and dark.</td>', 'The overall photo is a little hazy and dark.', '2003-09-11 10:28:41.000000', NULL, 1),
(415721, 36545, 2883, '<td valign="top">Nice use of the sky as background to bring out the colors. This might be better if more of the purple flower was shown or less of the green leaf. It has the feel of being incomplete.</td>', 'Nice use of the sky as background to bring out the colors. This might be better if more of the purple flower was shown or less of the green leaf. It has the feel of being incomplete.', '2003-09-11 10:29:44.000000', NULL, 1),
(415723, 36035, 2883, '<td valign="top">Perhaps a little too much cropping on the bottom end. The background is distracting, but the detail is good.</td>', 'Perhaps a little too much cropping on the bottom end. The background is distracting, but the detail is good.', '2003-09-11 10:30:33.000000', NULL, 1),
(415725, 36037, 2883, '<td valign="top">Wonderful composition. One of only a few that truly met the challenge of showing intimacy. The overall photo is a little fuzzy.</td>', 'Wonderful composition. One of only a few that truly met the challenge of showing intimacy. The overall photo is a little fuzzy.', '2003-09-11 10:31:44.000000', NULL, 1),
(415726, 36758, 2883, '<td valign="top">Nice coloring on the insect. It might have been a better photo shot at an angle so the insect doesn''t blend in as much.</td>', 'Nice coloring on the insect. It might have been a better photo shot at an angle so the insect doesn''t blend in as much.', '2003-09-11 10:32:43.000000', NULL, 1),
(415728, 36829, 2883, '<td valign="top">Good attempt at humor with the title. It photo is clear, but the composition might be better if the insect wasn''t centered, perhaps more to the lower right to enhance the idea of falling off.</td>', 'Good attempt at humor with the title. It photo is clear, but the composition might be better if the insect wasn''t centered, perhaps more to the lower right to enhance the idea of falling off.', '2003-09-11 10:34:06.000000', NULL, 1),
(415729, 36771, 2883, '<td valign="top">Good coloring in this photo. The clarity is a little off. Nice use of the flower to enhance the insect though.</td>', 'Good coloring in this photo. The clarity is a little off. Nice use of the flower to enhance the insect though.', '2003-09-11 10:34:50.000000', NULL, 1),
(415732, 36856, 2883, '<td valign="top">Great composition and use of the flower to give personality to the insect.</td>', 'Great composition and use of the flower to give personality to the insect.', '2003-09-11 10:35:30.000000', NULL, 1),
(415733, 36749, 2883, '<td valign="top">Great close-up and colors. Good lighting and composition.</td>', 'Great close-up and colors. Good lighting and composition.', '2003-09-11 10:36:10.000000', NULL, 1),
(415735, 36483, 2883, '<td valign="top">The shadows on the white background are a little distracting, as is the green blade comign straight at the camera.</td>', 'The shadows on the white background are a little distracting, as is the green blade comign straight at the camera.', '2003-09-11 10:36:59.000000', NULL, 1),
(415736, 36866, 2883, '<td valign="top">Nice, sharp black and white photo. It doesn''t really appear like it''s looking at the viewer as the title implies, though.</td>', 'Nice, sharp black and white photo. It doesn''t really appear like it''s looking at the viewer as the title implies, though.', '2003-09-11 10:37:49.000000', NULL, 1),
