(417218, 36760, 11022, '<td valign="top">Wonderful title.  Could use some thoughtful cropping to better showcase the bee.</td>', 'Wonderful title.  Could use some thoughtful cropping to better showcase the bee.', '2003-09-12 18:16:36.000000', NULL, 1),
(417219, 36086, 8125, '<td valign="top">This is a terrific shot - and I like your title.  The bee is so crisp and so clear.  Nice job!</td>', 'This is a terrific shot - and I like your title.  The bee is so crisp and so clear.  Nice job!', '2003-09-12 18:16:49.000000', NULL, 1),
(417222, 36754, 11022, '<td valign="top">Beautiful details.  A grasshopper with a name.  Great shot</td>', 'Beautiful details.  A grasshopper with a name.  Great shot', '2003-09-12 18:17:34.000000', NULL, 1),
