(417229, 36635, 11022, '<td valign="top">very interesting angle.</td>', 'very interesting angle.', '2003-09-12 18:20:18.000000', NULL, 1),
(417230, 36410, 8125, '<td valign="top">Nice macro - you captured a lot of this guy''s detail!  I would like to see him whole, but that''s the only comment I can make about this one...</td>', 'Nice macro - you captured a lot of this guy''s detail!  I would like to see him whole, but that''s the only comment I can make about this one...', '2003-09-12 18:20:21.000000', NULL, 1),
