(417239, 36851, 12075, '<td valign="top">amazing<br/>&amp; hello, new member here.</td>', 'amazing& hello, new member here.', '2003-09-12 18:24:01.000000', NULL, 1),
(417241, 36778, 11022, '<td valign="top">Excellent clarity and wonderful colors.</td>', 'Excellent clarity and wonderful colors.', '2003-09-12 18:24:49.000000', NULL, 1),
(417242, 36037, 8125, '<td valign="top">Original and funny!  Great idea...  The photo seems a little grainy.  The pillow is not as prominent because of a glare on the right side, maybe from your lighting source?  Otherwise, nice shot.</td>', 'Original and funny!  Great idea...  The photo seems a little grainy.  The pillow is not as prominent because of a glare on the right side, maybe from your lighting source?  Otherwise, nice shot.', '2003-09-12 18:24:52.000000', NULL, 1),
