(417247, 36446, 11022, '<td valign="top">Very clever.  Good job</td>', 'Very clever.  Good job', '2003-09-12 18:26:01.000000', NULL, 1),
(417248, 36547, 8125, '<td valign="top">Nice detail on the dragonfly!  It looks like the light might be too strong - but otherwise a nice shot</td>', 'Nice detail on the dragonfly!  It looks like the light might be too strong - but otherwise a nice shot', '2003-09-12 18:26:10.000000', NULL, 1),
(417249, 36785, 11022, '<td valign="top">Beautiful shot.  I love the lighting effect of this one; like it''s being spotlighted.  Good work.</td>', 'Beautiful shot.  I love the lighting effect of this one; like it''s being spotlighted.  Good work.', '2003-09-12 18:27:00.000000', NULL, 1),
(417252, 36470, 8125, '<td valign="top">Very nice shot!  Love the detail on this guy... great work!</td>', 'Very nice shot!  Love the detail on this guy... great work!', '2003-09-12 18:27:28.000000', NULL, 1),
(417255, 36203, 11022, '<td valign="top">Well, your title add so much menace to the shot I can''t stop shivering!    Great details.</td>', 'Well, your title add so much menace to the shot I can''t stop shivering!    Great details.', '2003-09-12 18:28:21.000000', NULL, 1),
(417259, 36775, 11022, '<td valign="top">Nice.  I like the angle and your beautiful muted background.</td>', 'Nice.  I like the angle and your beautiful muted background.', '2003-09-12 18:30:12.000000', NULL, 1),
(417260, 36742, 8125, '<td valign="top">Excellent!  Love the detail on the fly - focus and lighting is good.  The water drop on the leaf is perfect.  <br/> <br/>I might have cropped the photo just slightly tighter, the large space around the fly leaves my eyes to wander a bit, but that''s the only suggestion I have...</td>', 'Excellent!  Love the detail on the fly - focus and lighting is good.  The water drop on the leaf is perfect.   I might have cropped the photo just slightly tighter, the large space around the fly leaves my eyes to wander a bit, but that''s the only suggestion I have...', '2003-09-12 18:30:15.000000', NULL, 1),
(417263, 36785, 8125, '<td valign="top">Very nice shot, I like the detail and lighting.</td>', 'Very nice shot, I like the detail and lighting.', '2003-09-12 18:31:38.000000', NULL, 1),
(417265, 36846, 8125, '<td valign="top">These are not easy to get a photo of, and you''ve done a great job!  Love the wing detail and lighting is good.  The silky leaf is a nice accent.</td>', 'These are not easy to get a photo of, and you''ve done a great job!  Love the wing detail and lighting is good.  The silky leaf is a nice accent.', '2003-09-12 18:33:00.000000', NULL, 1),
