INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(417277, 36873, 8125, '<td valign="top">Very nice shot.  Good composition, lighting is good.  I see a ribbon in it''s future.  :-)</td>', 'Very nice shot.  Good composition, lighting is good.  I see a ribbon in it''s future.  :-)', '2003-09-12 18:38:20.000000', NULL, 1),
(417282, 36185, 8125, '<td valign="top">Very nice capture on this Mantis!</td>', 'Very nice capture on this Mantis!', '2003-09-12 18:40:15.000000', NULL, 1),
(417284, 36357, 8125, '<td valign="top">It''s terrific the way you were able to get him completely in the picture.  I just wish I could see him a little better.  But, this is their nature - to blend in.  Nice job</td>', 'It''s terrific the way you were able to get him completely in the picture.  I just wish I could see him a little better.  But, this is their nature - to blend in.  Nice job', '2003-09-12 18:43:54.000000', NULL, 1),
(417293, 36749, 8125, '<td valign="top">Very nice!  The detail is excellent.  I like the placement, lighting is good...</td>', 'Very nice!  The detail is excellent.  I like the placement, lighting is good...', '2003-09-12 18:56:54.000000', NULL, 1),
(417324, 36841, 9241, '<td valign="top">Too many things out of focus. They dont have much of a body, but I think it would help to see it. The out of focus foreground is drawing my eye much more than the legs are. sorry.3</td>', 'Too many things out of focus. They dont have much of a body, but I think it would help to see it. The out of focus foreground is drawing my eye much more than the legs are. sorry.3', '2003-09-12 19:26:18.000000', NULL, 1),
(417325, 36879, 9241, '<td valign="top">Nice attempt at a macro, but I think the focus is critical at this distance. There is nothing for my eye to focus on.</td>', 'Nice attempt at a macro, but I think the focus is critical at this distance. There is nothing for my eye to focus on.', '2003-09-12 19:28:06.000000', NULL, 1),
(417330, 36747, 9241, '<td valign="top">Yes I see the ant so what? there is no real subject at this distance. Why didn''t you get closer?</td>', 'Yes I see the ant so what? there is no real subject at this distance. Why didn''t you get closer?', '2003-09-12 19:30:58.000000', NULL, 1),
(417368, 36470, 9504, '<td valign="top">Stunning shot of this dragonfly!  Most of the ones I have seen haven''t captivated me like this one.  Fabulous!!</td>', 'Stunning shot of this dragonfly!  Most of the ones I have seen haven''t captivated me like this one.  Fabulous!!', '2003-09-12 20:17:19.000000', NULL, 1),
(417371, 36832, 9504, '<td valign="top">I wish the depth of field were a little deeper to get a true sense of this character.  If the depth of field were higher, I''d give this a near 10.   Vote: 7</td>', 'I wish the depth of field were a little deeper to get a true sense of this character.  If the depth of field were higher, I''d give this a near 10.   Vote: 7', '2003-09-12 20:18:59.000000', NULL, 1),
(417372, 36635, 9504, '<td valign="top">Great photo.  I just wish the eyes were more in focus...but othewise outstanding.  Great framing, fabulous angle -- I love it!</td>', 'Great photo.  I just wish the eyes were more in focus...but othewise outstanding.  Great framing, fabulous angle -- I love it!', '2003-09-12 20:20:11.000000', NULL, 1),
(417374, 36177, 9504, '<td valign="top">I love the ice in this photo.  The blue color is exceptional.  There is great contrast.  This bug is sure dark, by nature, huh?  Great job.  I''m bumping you up a number on second review!  Good luck...</td>', 'I love the ice in this photo.  The blue color is exceptional.  There is great contrast.  This bug is sure dark, by nature, huh?  Great job.  I''m bumping you up a number on second review!  Good luck...', '2003-09-12 20:21:14.000000', NULL, 1),
(417375, 36768, 9504, '<td valign="top">A little more depth of field would have been nice.  I feel there is too much blur in the picture for my tastes.  If the wings were in focus it would have be fabulous.  Great capture still!</td>', 'A little more depth of field would have been nice.  I feel there is too much blur in the picture for my tastes.  If the wings were in focus it would have be fabulous.  Great capture still!', '2003-09-12 20:22:03.000000', NULL, 1),
(417376, 36449, 9504, '<td valign="top">Exceptional angle...really cool shot.  8<br/></td>', 'Exceptional angle...really cool shot.  8', '2003-09-12 20:23:20.000000', NULL, 1),
(417377, 36287, 9504, '<td valign="top">This is a beautiful butterfly, but the background is kind of busy and takes away from the beauty of it.  While butterfiles are not easy to photograph, you can''t always pick and choose.</td>', 'This is a beautiful butterfly, but the background is kind of busy and takes away from the beauty of it.  While butterfiles are not easy to photograph, you can''t always pick and choose.', '2003-09-12 20:25:13.000000', NULL, 1),
(417379, 36459, 9504, '<td valign="top">Excellent photo, color, clarity, framing!  There is some tough competition in this challenge -- you''ll rank up there!</td>', 'Excellent photo, color, clarity, framing!  There is some tough competition in this challenge -- you''ll rank up there!', '2003-09-12 20:28:29.000000', NULL, 1),
(417380, 36780, 9504, '<td valign="top">Exceptional shot.  I haven''t seen one of these before.  The colors are magnificent!</td>', 'Exceptional shot.  I haven''t seen one of these before.  The colors are magnificent!', '2003-09-12 20:30:01.000000', NULL, 1),
(417381, 36471, 9504, '<td valign="top">Cool bug!!</td>', 'Cool bug!!', '2003-09-12 20:30:31.000000', NULL, 1),
(417382, 36778, 8125, '<td valign="top">Excellent capture.  I get these moths clinging to the outside of the house all the time.  They look big enough to be birds!  Clarity and lighting are great.  The purple flower adds interest.</td>', 'Excellent capture.  I get these moths clinging to the outside of the house all the time.  They look big enough to be birds!  Clarity and lighting are great.  The purple flower adds interest.', '2003-09-12 20:30:35.000000', NULL, 1),
(417384, 36754, 8125, '<td valign="top">Excellent macro.  Well done!</td>', 'Excellent macro.  Well done!', '2003-09-12 20:32:10.000000', NULL, 1),
(417385, 36530, 8125, '<td valign="top">This is a great macro subject - the image is a bit blurry - maybe out of focus a little?</td>', 'This is a great macro subject - the image is a bit blurry - maybe out of focus a little?', '2003-09-12 20:32:57.000000', NULL, 1),
(417467, 36448, 6100, '<td valign="top">Well, that''s one way to make the bug stay still!!</td>', 'Well, that''s one way to make the bug stay still!!', '2003-09-12 22:47:15.000000', NULL, 1),
(417509, 36873, 11022, '<td valign="top">Unique perspective.  I really like this and the more I look at it the better I like it.  Great composition and absolutely wonderful color.</td>', 'Unique perspective.  I really like this and the more I look at it the better I like it.  Great composition and absolutely wonderful color.', '2003-09-13 00:25:15.000000', NULL, 1),
(417510, 36823, 11022, '<td valign="top">Nicely different from the ordinary spider shot.<br/></td>', 'Nicely different from the ordinary spider shot.', '2003-09-13 00:28:27.000000', NULL, 1),
(417511, 36823, 9504, '<td valign="top">I absolutely love the droplets of water in the web, the black and white, the angle -- all around exceptional photo.</td>', 'I absolutely love the droplets of water in the web, the black and white, the angle -- all around exceptional photo.', '2003-09-13 00:28:34.000000', NULL, 1),
(417512, 36020, 11022, '<td valign="top">Really excellent macro shot.  Love the color in the eyes and the cool smile.</td>', 'Really excellent macro shot.  Love the color in the eyes and the cool smile.', '2003-09-13 00:30:49.000000', NULL, 1),
(417513, 36690, 11022, '<td valign="top">Certainly nice and close and the colors are good, but it is way too oversharpened to  my eye.</td>', 'Certainly nice and close and the colors are good, but it is way too oversharpened to  my eye.', '2003-09-13 00:32:27.000000', NULL, 1),
(417515, 36749, 11022, '<td valign="top">Nicely positioned and composed.</td>', 'Nicely positioned and composed.', '2003-09-13 00:36:18.000000', NULL, 1),
(417516, 36815, 11022, '<td valign="top">I''d stay out of that yard!</td>', 'I''d stay out of that yard!', '2003-09-13 00:36:53.000000', NULL, 1),
(417517, 36726, 11022, '<td valign="top">very cute~</td>', 'very cute~', '2003-09-13 00:37:43.000000', NULL, 1),
(417518, 36742, 11022, '<td valign="top">Beautiful focus and clarity, nice color and background blur.  Could be cropped differently for better effect.</td>', 'Beautiful focus and clarity, nice color and background blur.  Could be cropped differently for better effect.', '2003-09-13 00:38:51.000000', NULL, 1),
(417520, 36873, 11613, '<td valign="top">very cool pic</td>', 'very cool pic', '2003-09-13 00:44:59.000000', NULL, 1),
(417685, 36767, 3554, '<td valign="top">This shot is out of focus and my eye is immediately drawn to the bright spot under the light. Perhaps if you had focused the camera on the light itself it would have helped.</td>', 'This shot is out of focus and my eye is immediately drawn to the bright spot under the light. Perhaps if you had focused the camera on the light itself it would have helped.', '2003-09-13 01:49:36.000000', NULL, 1),
(417703, 36803, 3554, '<td valign="top">The flea looks dead which makes the shot sort of uninteresting.</td>', 'The flea looks dead which makes the shot sort of uninteresting.', '2003-09-13 01:56:04.000000', NULL, 1),
(417725, 36879, 3554, '<td valign="top">This shot has potential, if the eyes were in focus it would help a lot.</td>', 'This shot has potential, if the eyes were in focus it would help a lot.', '2003-09-13 01:59:47.000000', NULL, 1),
(417936, 36879, 3290, '<td valign="top">Almost good - you got nice and close- but too soft, I''m afraid.</td>', 'Almost good - you got nice and close- but too soft, I''m afraid.', '2003-09-13 13:38:33.000000', NULL, 1),
(417937, 36662, 3290, '<td valign="top">Nice and sharp - good exposure too. Subject gets a little lost in the background, though, and that blade of grass obscuring the mouth is unfortunate,</td>', 'Nice and sharp - good exposure too. Subject gets a little lost in the background, though, and that blade of grass obscuring the mouth is unfortunate,', '2003-09-13 13:39:34.000000', NULL, 1),
(417939, 36776, 3290, '<td valign="top">Wow, that''s cool! I take it that''s an enlarging mirror you''ve introduced? Nice effect - I''m amazed you could do it without the mantis leaving. Good idea, and nicely executed.</td>', 'Wow, that''s cool! I take it that''s an enlarging mirror you''ve introduced? Nice effect - I''m amazed you could do it without the mantis leaving. Good idea, and nicely executed.', '2003-09-13 13:41:22.000000', NULL, 1),
(417941, 36821, 3290, '<td valign="top">Nice front-on view, but could use a bit more DOF, IMHO.</td>', 'Nice front-on view, but could use a bit more DOF, IMHO.', '2003-09-13 13:42:56.000000', NULL, 1),
(417942, 36605, 3290, '<td valign="top">Good subject, nice pose. A bit overexposed, and could do with being a bit sharper. Like the composition, though.</td>', 'Good subject, nice pose. A bit overexposed, and could do with being a bit sharper. Like the composition, though.', '2003-09-13 13:43:54.000000', NULL, 1),
(417943, 36866, 3290, '<td valign="top">Good sharpness on the head - interesting choise to go for B&amp;W, but it works. A bit more DOF wouldn''t go amisee though.</td>', 'Good sharpness on the head - interesting choise to go for B&W, but it works. A bit more DOF wouldn''t go amisee though.', '2003-09-13 13:44:39.000000', NULL, 1),
(417944, 36247, 3290, '<td valign="top">Pretty. Nicely blurred background isolates the subject well. A bit more sharpness wouldn''t hurt, though, and there''s quite a lot of fringing.</td>', 'Pretty. Nicely blurred background isolates the subject well. A bit more sharpness wouldn''t hurt, though, and there''s quite a lot of fringing.', '2003-09-13 13:45:43.000000', NULL, 1),
(417945, 36802, 3290, '<td valign="top">Nice clear shot with good sharpness where it''s sharp, but the lack of sharpness on the antennae of the uppermost wasp spoils it somewhat. Lovely clear colours and exposure. Which camera is this?</td>', 'Nice clear shot with good sharpness where it''s sharp, but the lack of sharpness on the antennae of the uppermost wasp spoils it somewhat. Lovely clear colours and exposure. Which camera is this?', '2003-09-13 13:47:35.000000', NULL, 1),
(417946, 36557, 3290, '<td valign="top">Great colours. Nice and sharp too. Not a lot wrong with this one. The two bright flower heads to the left of the ''hoppe''s head are a distraction - clone them out for the print. Good one.</td>', 'Great colours. Nice and sharp too. Not a lot wrong with this one. The two bright flower heads to the left of the ''hoppe''s head are a distraction - clone them out for the print. Good one.', '2003-09-13 13:48:59.000000', NULL, 1),
(417947, 36742, 3290, '<td valign="top">Hoverlfies are one of my favourite subjects - you''ve done a good jobe here. Nicely exposed and sharp. Perhaps crop a bit tighter so we can see more of the fly?</td>', 'Hoverlfies are one of my favourite subjects - you''ve done a good jobe here. Nicely exposed and sharp. Perhaps crop a bit tighter so we can see more of the fly?', '2003-09-13 13:49:59.000000', NULL, 1),
(417961, 36287, 9168, '<td valign="top">Needs a slight rotation.  Otherwise, its a neat shot.  I like the textures.</td>', 'Needs a slight rotation.  Otherwise, its a neat shot.  I like the textures.', '2003-09-13 14:10:37.000000', NULL, 1),
(417962, 36820, 9168, '<td valign="top">I hate flies.  However, I like this shot.  Asymmetrical, rule of thirds, etc..</td>', 'I hate flies.  However, I like this shot.  Asymmetrical, rule of thirds, etc..', '2003-09-13 14:13:40.000000', NULL, 1),
(417966, 36691, 9168, '<td valign="top">Some color correction to get ride of the blue hue would have made this shot.</td>', 'Some color correction to get ride of the blue hue would have made this shot.', '2003-09-13 14:28:14.000000', NULL, 1),
(417993, 36754, 7778, '<td valign="top">Being no expert of insects, this macro proides wonderful crisp detail while also revealing his habitat or stomping grounds. Apart from the educational value it will hold for most of us, it is aptly exposed, with colour and hues appearing true to nature. The image is free of any distracting or redundant elements. Composition... examplary. The near-white background found or created here provides a welcome  and fresh counterbalance to the Cimmerian tones and shapes which distinguish this creature viewed at such proximity. The absence of a decorative border, particularly, stresses the integrity of this impeccable shot.</td>', 'Being no expert of insects, this macro proides wonderful crisp detail while also revealing his habitat or stomping grounds. Apart from the educational value it will hold for most of us, it is aptly exposed, with colour and hues appearing true to nature. The image is free of any distracting or redundant elements. Composition... examplary. The near-white background found or created here provides a welcome  and fresh counterbalance to the Cimmerian tones and shapes which distinguish this creature viewed at such proximity. The absence of a decorative border, particularly, stresses the integrity of this impeccable shot.', '2003-09-13 15:17:08.000000', NULL, 1),
(418011, 36833, 7778, '<td valign="top">This image, aptly, lacks the extreme sharpness evident in some competing entries. Instead, the apparent emphasis is on the natural light pervading all. The butterfly''s white wings, especially via the shadow of one visible through the translucent other, add an unusual and incidental interest. The slight overexposure that has been allowed onto the inner side of the right wing marks the only pure-white area in the photo, precisely at point of focus. <br/> <br/>Apart from providing a clear anchor for the eye, these effects also stimulate a latent  s e r a p h i c  interpretation or sense. <br/> <br/>The inclusion of a series of blossoming plant stems extending left to right into the picture provides both an environment and compositional soundness. The background, while richly luminous, adds much to the particular aesthetic of the subject without being distracting.<br/> <br/>A great photograph!</td>', 'This image, aptly, lacks the extreme sharpness evident in some competing entries. Instead, the apparent emphasis is on the natural light pervading all. The butterfly''s white wings, especially via the shadow of one visible through the translucent other, add an unusual and incidental interest. The slight overexposure that has been allowed onto the inner side of the right wing marks the only pure-white area in the photo, precisely at point of focus.  Apart from providing a clear anchor for the eye, these effects also stimulate a latent  s e r a p h i c  interpretation or sense.  The inclusion of a series of blossoming plant stems extending left to right into the picture provides both an environment and compositional soundness. The background, while richly luminous, adds much to the particular aesthetic of the subject without being distracting. A great photograph!', '2003-09-13 16:00:56.000000', NULL, 1),
(418020, 36880, 11926, '<td valign="top">Nice shot, would a tighter crop eliminate some of the distracting background?</td>', 'Nice shot, would a tighter crop eliminate some of the distracting background?', '2003-09-13 17:04:42.000000', NULL, 1),
(418021, 36754, 11926, '<td valign="top">Really nice...  Great color, and simple.</td>', 'Really nice...  Great color, and simple.', '2003-09-13 17:07:04.000000', NULL, 1),
(418022, 36557, 11926, '<td valign="top">Really nice detail, simple - not much in the frame to distract from the insect.</td>', 'Really nice detail, simple - not much in the frame to distract from the insect.', '2003-09-13 17:08:57.000000', NULL, 1),
(418023, 36446, 11926, '<td valign="top">Great concept!</td>', 'Great concept!', '2003-09-13 17:09:26.000000', NULL, 1),
(418027, 36775, 9448, '<td valign="top">Thats no macro</td>', 'Thats no macro', '2003-09-13 17:49:53.000000', NULL, 1),
(418082, 36292, 7038, '<td valign="top">Excellent idea and composition.  Almost perfect DOF too.  The lighting seems a little soft on the left side of the picture, possibly some soft lighting from this side wouldve evened the lighting out.  Still not enough to detract from the picture though. 10</td>', 'Excellent idea and composition.  Almost perfect DOF too.  The lighting seems a little soft on the left side of the picture, possibly some soft lighting from this side wouldve evened the lighting out.  Still not enough to detract from the picture though. 10', '2003-09-13 20:55:14.000000', NULL, 1),
(418097, 36364, 11873, '<td valign="top">Great subjet. I take a lot of Argiope aurantia pictures myself. I have to say, though, the house or garage makes a terrible background, and the lighting is too harsh and flat/frontal. It''s a good start.</td>', 'Great subjet. I take a lot of Argiope aurantia pictures myself. I have to say, though, the house or garage makes a terrible background, and the lighting is too harsh and flat/frontal. It''s a good start.', '2003-09-13 21:02:48.000000', NULL, 1),
(418115, 36881, 11873, '<td valign="top">If I were to shoot this subject, I would try to move over to the left to get a better profile of it, and use an aperture that makes the background out of focus, but that''s just me. Here''s an instance where I think the "no spot retouching" rule is idiotic. I believe that we should be able to correct things like that one pixel in the upper-right corner on the tree that is obviously not the correct color.</td>', 'If I were to shoot this subject, I would try to move over to the left to get a better profile of it, and use an aperture that makes the background out of focus, but that''s just me. Here''s an instance where I think the "no spot retouching" rule is idiotic. I believe that we should be able to correct things like that one pixel in the upper-right corner on the tree that is obviously not the correct color.', '2003-09-13 21:07:33.000000', NULL, 1),
(418124, 36816, 11873, '<td valign="top">If I were to shoot this subject, I would try to position the camera so it looks like we are at the wasp''s level rather than above it. The highlights are a bit blown-out.</td>', 'If I were to shoot this subject, I would try to position the camera so it looks like we are at the wasp''s level rather than above it. The highlights are a bit blown-out.', '2003-09-13 21:11:12.000000', NULL, 1),
(418132, 36690, 11873, '<td valign="top">This is excellent. Great color tone and saturation, and no distractions in the background. The composition is good, too. I like it. Is it a June Beetle?</td>', 'This is excellent. Great color tone and saturation, and no distractions in the background. The composition is good, too. I like it. Is it a June Beetle?', '2003-09-13 21:13:16.000000', NULL, 1),
(418137, 36874, 11873, '<td valign="top">This would be much better if the color was richer.</td>', 'This would be much better if the color was richer.', '2003-09-13 21:14:29.000000', NULL, 1),
(418158, 36697, 11873, '<td valign="top">Pretty good, but the image could have used some enhancement. It looks purplish.</td>', 'Pretty good, but the image could have used some enhancement. It looks purplish.', '2003-09-13 21:18:50.000000', NULL, 1),
(418177, 36435, 11873, '<td valign="top">Good subject, a damselfly. Shutter speed was too slow; this must have been hand held. The composition could use improvement. The plant that the damselfly is hanging on is dead and detracts from the picture.</td>', 'Good subject, a damselfly. Shutter speed was too slow; this must have been hand held. The composition could use improvement. The plant that the damselfly is hanging on is dead and detracts from the picture.', '2003-09-13 21:22:44.000000', NULL, 1),
(418194, 36880, 11873, '<td valign="top">Nice and crisp on the left wing, but not on the eyes or other wing. Lacks color fidelity. The ugly, dead-looking flower in the background on the left needs to go. I don''t agree with the "no spot retouching" rule for stuff like that.</td>', 'Nice and crisp on the left wing, but not on the eyes or other wing. Lacks color fidelity. The ugly, dead-looking flower in the background on the left needs to go. I don''t agree with the "no spot retouching" rule for stuff like that.', '2003-09-13 21:27:01.000000', NULL, 1),
(418209, 36778, 11873, '<td valign="top">The motion of the subject is TOO frozen. It would actually be better with the wings a little bit blurry to show that they are flapping. It looks like a dart stuck in a dart board. Direct flash is harsh and unflattering.</td>', 'The motion of the subject is TOO frozen. It would actually be better with the wings a little bit blurry to show that they are flapping. It looks like a dart stuck in a dart board. Direct flash is harsh and unflattering.', '2003-09-13 21:29:37.000000', NULL, 1),
(418215, 36471, 11873, '<td valign="top">Depth of field is good. The leaf in the background is hideous.</td>', 'Depth of field is good. The leaf in the background is hideous.', '2003-09-13 21:30:50.000000', NULL, 1),
(418247, 36678, 11873, '<td valign="top">I see berries, berries, berries. The insect is like an afterthought. The depth-of-field is shallow. Lighting is flat and harsh flash. Shutter speed too slow.</td>', 'I see berries, berries, berries. The insect is like an afterthought. The depth-of-field is shallow. Lighting is flat and harsh flash. Shutter speed too slow.', '2003-09-13 21:36:55.000000', NULL, 1),
(418259, 36815, 8860, '<td valign="top">Focus is on centre of the grub rather than an interesting part (head or rear).</td>', 'Focus is on centre of the grub rather than an interesting part (head or rear).', '2003-09-13 21:39:21.000000', NULL, 1),
(418263, 36806, 11873, '<td valign="top">Highlights are blown out. Image lacks color fidelity and looks a little too saturated.</td>', 'Highlights are blown out. Image lacks color fidelity and looks a little too saturated.', '2003-09-13 21:39:53.000000', NULL, 1),
(418270, 36242, 8860, '<td valign="top">Image is a bit harsh making the subject a little confusing. Looks like an interesting metamorphosis scenario here. The composition could have been improved by filling the frame more with the critter.</td>', 'Image is a bit harsh making the subject a little confusing. Looks like an interesting metamorphosis scenario here. The composition could have been improved by filling the frame more with the critter.', '2003-09-13 21:41:19.000000', NULL, 1),
(418280, 36796, 8860, '<td valign="top">Weirdly, this hapless wasp looks like it''s floating. How was it killed - it doesn''t looked squashed? I would have cropped the left side, and perhaps reduced sharpen levels a touch.</td>', 'Weirdly, this hapless wasp looks like it''s floating. How was it killed - it doesn''t looked squashed? I would have cropped the left side, and perhaps reduced sharpen levels a touch.', '2003-09-13 21:43:31.000000', NULL, 1),
(418282, 36607, 11873, '<td valign="top">Blur from camera-shake is evident. The subject is very interesting; I wish we had that species of spider around here. The color fidelity isn''t very good. The composition is alright, though.</td>', 'Blur from camera-shake is evident. The subject is very interesting; I wish we had that species of spider around here. The color fidelity isn''t very good. The composition is alright, though.', '2003-09-13 21:43:40.000000', NULL, 1),
(418293, 36728, 8860, '<td valign="top">Your title is a bit odd, but this is a good capture of what might turn out to be the last one-day stand for that fella! Beautiful spiders.</td>', 'Your title is a bit odd, but this is a good capture of what might turn out to be the last one-day stand for that fella! Beautiful spiders.', '2003-09-13 21:45:37.000000', NULL, 1),
(418305, 36694, 8860, '<td valign="top">Focus is a bit misplaced - but she''s a beauty. Colour is a little muted.</td>', 'Focus is a bit misplaced - but she''s a beauty. Colour is a little muted.', '2003-09-13 21:47:16.000000', NULL, 1),
(418306, 36054, 11873, '<td valign="top">The colors are too saturated and too red, and too much sharpening was applied (look at the antennae).</td>', 'The colors are too saturated and too red, and too much sharpening was applied (look at the antennae).', '2003-09-13 21:47:17.000000', NULL, 1),
(418311, 36691, 8860, '<td valign="top">Focus is off-target (head) and colours a bit muted.</td>', 'Focus is off-target (head) and colours a bit muted.', '2003-09-13 21:48:05.000000', NULL, 1),
(418323, 36032, 8860, '<td valign="top">Nice to see some lizard-food being given some creative treatment! Image is a bit dull though, with too little to hold interest for long.</td>', 'Nice to see some lizard-food being given some creative treatment! Image is a bit dull though, with too little to hold interest for long.', '2003-09-13 21:50:11.000000', NULL, 1),
(418329, 36301, 11873, '<td valign="top">Colors are way off; too blue. You can see the effects of too much jpeg compression. The composition is okay, but would be better if it wasn''t "looming over" the subject.</td>', 'Colors are way off; too blue. You can see the effects of too much jpeg compression. The composition is okay, but would be better if it wasn''t "looming over" the subject.', '2003-09-13 21:51:17.000000', NULL, 1),
(418344, 36672, 8860, '<td valign="top">Hoverfly I think - a bit off-focus.</td>', 'Hoverfly I think - a bit off-focus.', '2003-09-13 21:55:36.000000', NULL, 1),
(418354, 36091, 11873, '<td valign="top">That''s a cicada''s ex-skin, not a cicada. Not a very challenging subject considering it''s nothing but an exoskeleton and can''t move. The hair in the picture could have been removed. Depth of field is too shallow. Looks like it was taken under an indoor table lamp, hence the yellowish-red hue.</td>', 'That''s a cicada''s ex-skin, not a cicada. Not a very challenging subject considering it''s nothing but an exoskeleton and can''t move. The hair in the picture could have been removed. Depth of field is too shallow. Looks like it was taken under an indoor table lamp, hence the yellowish-red hue.', '2003-09-13 21:56:56.000000', NULL, 1),
(418362, 36691, 11873, '<td valign="top">Color is too cyan. The background is distracting and unnatural-looking.</td>', 'Color is too cyan. The background is distracting and unnatural-looking.', '2003-09-13 21:58:08.000000', NULL, 1),
(418372, 36429, 11873, '<td valign="top">The building in the background is disturbingly tilted. The photo would be better without the building. Looks like it was taken hand-held.</td>', 'The building in the background is disturbingly tilted. The photo would be better without the building. Looks like it was taken hand-held.', '2003-09-13 22:00:25.000000', NULL, 1),
(418376, 36192, 11873, '<td valign="top">Nice subject, horrible exposure and composition, though. The spiderweb and man-made objects could have been cropped out simply by moving over to the left and down with the camera. With a digital camera, there is no excuse for underexposure, since you can preview your images immediately.</td>', 'Nice subject, horrible exposure and composition, though. The spiderweb and man-made objects could have been cropped out simply by moving over to the left and down with the camera. With a digital camera, there is no excuse for underexposure, since you can preview your images immediately.', '2003-09-13 22:03:57.000000', NULL, 1),
(418377, 36558, 11873, '<td valign="top">That leaf poking in on the upper-right has to go. Another instance where I disagree with the "no spot retouching" rule. Too contrasty.</td>', 'That leaf poking in on the upper-right has to go. Another instance where I disagree with the "no spot retouching" rule. Too contrasty.', '2003-09-13 22:07:26.000000', NULL, 1),
(418378, 36287, 11873, '<td valign="top">Looks too "staged" on that concrete.</td>', 'Looks too "staged" on that concrete.', '2003-09-13 22:08:04.000000', NULL, 1),
(418379, 36800, 11873, '<td valign="top">This has nothing to do with its title.</td>', 'This has nothing to do with its title.', '2003-09-13 22:09:43.000000', NULL, 1),
(418385, 36747, 11873, '<td valign="top">I see a tree with a tiny, ant-shaped speck on it. I see a house and flora and a mountain or clouds.</td>', 'I see a tree with a tiny, ant-shaped speck on it. I see a house and flora and a mountain or clouds.', '2003-09-13 22:26:04.000000', NULL, 1),
(418419, 36823, 11034, '<td valign="top">My fav.</td>', 'My fav.', '2003-09-14 00:09:06.000000', NULL, 1),
(418444, 36856, 11873, '<td valign="top">This is a decent photograph, but since the subject of the photo is supposed to be the insect, and the lily is dominant, I can''t give it a good rating. Crop it so the dragonfly is the subject, and it would have been much better for this challenge.</td>', 'This is a decent photograph, but since the subject of the photo is supposed to be the insect, and the lily is dominant, I can''t give it a good rating. Crop it so the dragonfly is the subject, and it would have been much better for this challenge.', '2003-09-14 01:03:53.000000', NULL, 1),
(418446, 36756, 11873, '<td valign="top">More interesting than average subject, but the composition seems wrong. The grey in the background detracts from the image, too.</td>', 'More interesting than average subject, but the composition seems wrong. The grey in the background detracts from the image, too.', '2003-09-14 01:06:24.000000', NULL, 1),
(418447, 36841, 11873, '<td valign="top">Great idea, but was it an idea, or merely an accident? The depth of field is shallow and the image seems like it was not carefully composed.</td>', 'Great idea, but was it an idea, or merely an accident? The depth of field is shallow and the image seems like it was not carefully composed.', '2003-09-14 01:11:47.000000', NULL, 1),
(418448, 36247, 11873, '<td valign="top">Looks like it was taken hand held. Colors are too bluish/cyan.</td>', 'Looks like it was taken hand held. Colors are too bluish/cyan.', '2003-09-14 01:12:37.000000', NULL, 1),
(418450, 36846, 11873, '<td valign="top">Nice damselfly. The background is colorful, which can be good, but since it is more colorful than the subject, it detracts from the image. It makes it look like somebody''s yard or patio. Is that where this was taken? The white speck on the leaf is something that makes me disagree with the "no spot retouching" rule.</td>', 'Nice damselfly. The background is colorful, which can be good, but since it is more colorful than the subject, it detracts from the image. It makes it look like somebody''s yard or patio. Is that where this was taken? The white speck on the leaf is something that makes me disagree with the "no spot retouching" rule.', '2003-09-14 01:16:48.000000', NULL, 1),
(418454, 36357, 11873, '<td valign="top">Terrific subject. The angle is not very good, though. It would look much better if the camera was in front of the mantis or to the side, rather than "looming over" the mantis. That plant is good for the praying mantis to hide in, but not very good for a photograph.</td>', 'Terrific subject. The angle is not very good, though. It would look much better if the camera was in front of the mantis or to the side, rather than "looming over" the mantis. That plant is good for the praying mantis to hide in, but not very good for a photograph.', '2003-09-14 01:19:53.000000', NULL, 1),
(418456, 36545, 11873, '<td valign="top">Great monarch, but the chewed-up leaf and the angle of the stem detract from the image.</td>', 'Great monarch, but the chewed-up leaf and the angle of the stem detract from the image.', '2003-09-14 01:21:20.000000', NULL, 1),
(418458, 36779, 11873, '<td valign="top">Great job at getting close, but the red fabric makes it look obviously staged. The image needs some serious enhancement to it''s tonal range. Could use some sharpening, also.</td>', 'Great job at getting close, but the red fabric makes it look obviously staged. The image needs some serious enhancement to it''s tonal range. Could use some sharpening, also.', '2003-09-14 01:23:59.000000', NULL, 1),
(418461, 36557, 11873, '<td valign="top">Nice and clear with good color fidelity and sharpness. Grasshoppers aren''t the most challenging subject, in my opinion. I find them much too easy to photograph and rather boring.</td>', 'Nice and clear with good color fidelity and sharpness. Grasshoppers aren''t the most challenging subject, in my opinion. I find them much too easy to photograph and rather boring.', '2003-09-14 01:26:01.000000', NULL, 1),
(418463, 36020, 11873, '<td valign="top">I''m impressed that someone else has managed to get this close to a dragonfly. Good job! But the man-made, unnatural quality of the plastic mesh detracts from the overall quality of the image.</td>', 'I''m impressed that someone else has managed to get this close to a dragonfly. Good job! But the man-made, unnatural quality of the plastic mesh detracts from the overall quality of the image.', '2003-09-14 01:27:59.000000', NULL, 1),
(418464, 36857, 11873, '<td valign="top">Not a very challenging subject. Looks like a "snapshot". Is that a praying mantis or a horse?</td>', 'Not a very challenging subject. Looks like a "snapshot". Is that a praying mantis or a horse?', '2003-09-14 01:29:15.000000', NULL, 1),
(418467, 36477, 11873, '<td valign="top">Looks like it was taken in a terrarium. Whatever they are eating looks disgusting.</td>', 'Looks like it was taken in a terrarium. Whatever they are eating looks disgusting.', '2003-09-14 01:31:21.000000', NULL, 1),
(418468, 36717, 11873, '<td valign="top">Not at all a challenging subject.</td>', 'Not at all a challenging subject.', '2003-09-14 01:32:25.000000', NULL, 1),
(418474, 36832, 9441, '<td valign="top">I love it!  So cute!  Wonderful closeup!!!!!!</td>', 'I love it!  So cute!  Wonderful closeup!!!!!!', '2003-09-14 01:39:35.000000', NULL, 1),
(418475, 36340, 9441, '<td valign="top">Captured great detail...good closeup...very, very good photo...</td>', 'Captured great detail...good closeup...very, very good photo...', '2003-09-14 01:40:26.000000', NULL, 1),
(418476, 36203, 11873, '<td valign="top">Good subject, but I don''t think a photo of a spider should get a good rating when the challenge calls for insects and an Argiope aurantia is an arachnid. The towel makes it look too staged and unnatural.</td>', 'Good subject, but I don''t think a photo of a spider should get a good rating when the challenge calls for insects and an Argiope aurantia is an arachnid. The towel makes it look too staged and unnatural.', '2003-09-14 01:40:57.000000', NULL, 1),
(418477, 36690, 9441, '<td valign="top">very good closeup view...</td>', 'very good closeup view...', '2003-09-14 01:41:13.000000', NULL, 1),
(418478, 36629, 11873, '<td valign="top">A dead butterfly doesn''t seem like a very challenging subject.</td>', 'A dead butterfly doesn''t seem like a very challenging subject.', '2003-09-14 01:41:36.000000', NULL, 1),
(418480, 36678, 9441, '<td valign="top">good photo of the plant, but the insect is somewhat blurred...<br/><br/><i>Message edited by author 2003-09-19 15:23:40.</i></td>', 'good photo of the plant, but the insect is somewhat blurred...', '2003-09-14 01:42:43.000000', '2003-09-19 16:23:40.000000', 1),
(418482, 36558, 9441, '<td valign="top">Wow!  Awesome photo....wonderfully done!</td>', 'Wow!  Awesome photo....wonderfully done!', '2003-09-14 01:45:00.000000', NULL, 1),
