(419145, 36020, 4090, '<td valign="top">Congratulations Jacko on the ribbon and new member of the family.</td>', 'Congratulations Jacko on the ribbon and new member of the family.', '2003-09-15 02:28:18.000000', NULL, 0),
(419147, 36459, 4090, '<td valign="top">Congratulations bob on yet another fine photo.</td>', 'Congratulations bob on yet another fine photo.', '2003-09-15 02:30:04.000000', NULL, 0),
(419148, 36873, 4090, '<td valign="top">Congratulations Tom on a great photo and also your first ribbon.<br/><br/><i>Message edited by author 2003-09-15 01:31:45.</i></td>', 'Congratulations Tom on a great photo and also your first ribbon.', '2003-09-15 02:31:27.000000', '2003-09-15 02:31:45.000000', 0),
(419149, 36802, 7350, '<td valign="top">I''m not sure how it always happens, I had no idea this was your shot.  But, I gave it a 10 (you can see from my comment below).  Focus is fantastic.  I never realized that the yellow and black is so distinctive - kind of like a wasp "fingerprint."  The yellow color is so vibrant - I''m sure you "souped it up" a little in post-processing.  Perhaps the only tiny thing that I would change, that you really don''t have any control over, is that wasp in the left foreground.  I kinda wish I could just see the one that''s out, and the one that''s sticking his (her?) head out the hole, and that''s it.  However, there''s a lot of personality in this shot.</td>', 'I''m not sure how it always happens, I had no idea this was your shot.  But, I gave it a 10 (you can see from my comment below).  Focus is fantastic.  I never realized that the yellow and black is so distinctive - kind of like a wasp "fingerprint."  The yellow color is so vibrant - I''m sure you "souped it up" a little in post-processing.  Perhaps the only tiny thing that I would change, that you really don''t have any control over, is that wasp in the left foreground.  I kinda wish I could just see the one that''s out, and the one that''s sticking his (her?) head out the hole, and that''s it.  However, there''s a lot of personality in this shot.', '2003-09-15 02:33:23.000000', NULL, 0),
(419151, 36824, 3290, '<td valign="top">Hi Scott. Well done with this shot. I thought this was the best shot of the challenge.</td>', 'Hi Scott. Well done with this shot. I thought this was the best shot of the challenge.', '2003-09-15 02:36:35.000000', NULL, 0),
(419153, 36529, 10275, '<td valign="top">Oh, wow, yours is actually very good. I love the colours - the reddish legs and spotted back. You have nice detail in the eyes as well. It''s actually interesting that we both picked a hopper with our cameras being so similar in the macro range.<br/> <br/>I took me few seconds to giggle on the title.</td>', 'Oh, wow, yours is actually very good. I love the colours - the reddish legs and spotted back. You have nice detail in the eyes as well. It''s actually interesting that we both picked a hopper with our cameras being so similar in the macro range. I took me few seconds to giggle on the title.', '2003-09-15 02:37:22.000000', NULL, 0),
(419155, 36020, 3290, '<td valign="top">Congrats, Jacko. Great detail and colours in the eyes. Well done.</td>', 'Congrats, Jacko. Great detail and colours in the eyes. Well done.', '2003-09-15 02:37:57.000000', NULL, 0),
(419156, 36459, 3290, '<td valign="top">Well done, Bob. Congratulations on an attractive shot. Keep it up!</td>', 'Well done, Bob. Congratulations on an attractive shot. Keep it up!', '2003-09-15 02:39:31.000000', NULL, 0),
(419158, 36873, 3290, '<td valign="top">Congratulations Tom. A clean, clear attractive shot.</td>', 'Congratulations Tom. A clean, clear attractive shot.', '2003-09-15 02:41:33.000000', NULL, 0),
(419159, 36829, 7706, '<td valign="top">Way to go, thats a great score :) Love the colors in this shot :) I don''t know how people get shots like this. I never see any interesting insects outside lol</td>', 'Way to go, thats a great score :) Love the colors in this shot :) I don''t know how people get shots like this. I never see any interesting insects outside lol', '2003-09-15 02:41:58.000000', NULL, 0),
(419164, 36873, 10084, '<td valign="top">Great composition. The blueness of the water really sets the flower apart and the color of the ladybug really sets itself apart from the flower. These three layers give it a great depth of field. <br/> <br/>An incredibly beautiful shot. It would make for a great summer greeting card or a postcard.</td>', 'Great composition. The blueness of the water really sets the flower apart and the color of the ladybug really sets itself apart from the flower. These three layers give it a great depth of field.  An incredibly beautiful shot. It would make for a great summer greeting card or a postcard.', '2003-09-15 02:56:07.000000', NULL, 0),
(419171, 36824, 7350, '<td valign="top">I gave it a 10.  This is a fantastic macro shot, and I can''t believe it didn''t take blue ribbon.  Congratulations on a wonderful capture.</td>', 'I gave it a 10.  This is a fantastic macro shot, and I can''t believe it didn''t take blue ribbon.  Congratulations on a wonderful capture.', '2003-09-15 03:15:39.000000', NULL, 0),
(419215, 36020, 2780, '<td valign="top">Congrats jacko :) Amazing photo!</td>', 'Congrats jacko :) Amazing photo!', '2003-09-15 04:17:26.000000', NULL, 0),
(419264, 36020, 7086, '<td valign="top">Congrats Jacko, what a week for you!</td>', 'Congrats Jacko, what a week for you!', '2003-09-15 05:16:03.000000', NULL, 0),
(419285, 36020, 2178, '<td valign="top">Great job man! Awesome macro. !</td>', 'Great job man! Awesome macro. !', '2003-09-15 07:19:46.000000', NULL, 0),
(419286, 36459, 2178, '<td valign="top">Nice Bob! Your really kickin it into high gear with the Optio :)</td>', 'Nice Bob! Your really kickin it into high gear with the Optio :)', '2003-09-15 07:20:59.000000', NULL, 0),
(419292, 36020, 9448, '<td valign="top">Congrats on the ribbon jacko :) Amazing photo! And congrats on the new family member :)</td>', 'Congrats on the ribbon jacko :) Amazing photo! And congrats on the new family member :)', '2003-09-15 07:51:41.000000', NULL, 0),
(419305, 36020, 5783, '<td valign="top">WoW i think this macro is awesome well done!</td>', 'WoW i think this macro is awesome well done!', '2003-09-15 08:40:35.000000', NULL, 0),
